    p.append(_txt(438, 176, "λ inférieur à λc  →  écrasement, on vérifie Re", 11, OK, "start", True))
    p.append(_txt(438, 200, "λ supérieur à λc  →  FLAMBEMENT, on vérifie Euler", 11, ALERTE, "start", True))
    p.append(_txt(438, 228, "λc = π √(E/Re) ≈ 94 pour un S235", 11, TRAIT, "start", True))
    p.append(f"<rect x='40' y='275' width='680' height='90' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 298, "Le flambement est BRUTAL : pas de déformation qui prévient, la ruine est instantanée.", 12, TRAIT, "start", True))
