    p.append(_txt(560, 192, "à la section", 10, FIN, "middle"))
    p.append(f"<circle cx='680' cy='120' r='42' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<path d='M680,78 a 42,42 0 0,1 30,72' fill='none' stroke='{OK}' stroke-width='2' marker-end='url(#t2)'/>")
    p.append(_txt(680, 178, "τ : DANS le plan", 10, OK, "middle", True))
    p.append(_txt(680, 192, "de la section", 10, FIN, "middle"))
    p.append(f"<rect x='40' y='225' width='680' height='140' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 250, "σ et τ n'agissent pas dans la même direction : les additionner n'a aucun sens physique.",
                  12, TRAIT, "start", True))
