# ===========================================================================
# 49. LA GAMME D'USINAGE : L'ORDRE DES OPÉRATIONS
# ===========================================================================

def gamme_usinage():
    p = [_txt(40, 26, "Une gamme, c'est la suite ordonnée des opérations — et l'ordre n'est jamais libre :",
              13, TRAIT, "start", True)]
    etapes = [("10", "Brut", "barre, brut de fonderie, tôle", FIN),
              ("20", "Surfaçage de référence", "on crée d'abord LA face qui servira de référence", ALESAGE),
              ("30", "Ébauche", "on enlève le gros, vite, en laissant 1 à 2 mm", ALESAGE),
              ("40", "Traitement thermique", "il DÉFORME : d'où sa place ici, jamais après", ALERTE),
              ("50", "Finition", "on rattrape les déformations et on tient les cotes", OK),
              ("60", "Perçages et taraudages", "après la finition des faces d'appui", OK),
              ("70", "Rectification", "seulement sur les portées qui l'exigent", OK),
              ("80", "Contrôle", "on vérifie ce qui a été spécifié, pas tout", TRAIT)]
    y = 58
    for _i, (num, titre, detail, couleur) in enumerate(etapes):
        # le numéro de chaque étape s'éclaire l'un après l'autre, dans l'ordre : on VOIT
        # la gamme se dérouler et qu'aucune étape ne peut être prise avant son tour.
        p.append(f"<rect x='55' y='{y}' width='660' height='36' rx='5' fill='#ffffff' stroke='{couleur}' stroke-width='1.5'/>")
        p.append(f"<rect x='55' y='{y}' width='46' height='36' rx='5' fill='{couleur}' opacity='0.25'>"
                 f"<animate attributeName='opacity' values='0.25;0.75;0.25;0.25;0.25;0.25;0.25;0.25' "
                 f"dur='4.8s' begin='{_i * 0.55}s' repeatCount='indefinite'/></rect>")
        p.append(_txt(78, y + 23, num, 12, couleur, "middle", True))
        p.append(_txt(115, y + 16, titre, 12, TRAIT, "start", True))
        p.append(_txt(115, y + 30, detail, 10, FIN))
        y += 42
    p.append(f"<rect x='40' y='{y + 6}' width='680' height='66' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, y + 29, "La règle qui commande tout : ÉBAUCHE → TRAITEMENT → FINITION.", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 49, "Usiner à la cote avant de tremper, c'est jeter la pièce : elle sort du four déformée.", 12, FIN))
    p.append(_txt(56, y + 67, "Et on part toujours d'une surface de référence usinée, jamais d'une surface brute.", 11, ALERTE))
    return _svg("".join(p), 760, y + 90)


# ===========================================================================
# 50. LA GÉOMÉTRIE D'UN ENGRENAGE
# ===========================================================================

def geometrie_engrenage():
    p = [_txt(40, 26, "Tout part du module m — la taille d'une dent :", 13, TRAIT, "start", True)]
    cx, cy = 250, 190
    # la roue dentée tourne lentement sur elle-même : on VOIT une vraie roue, pas
    # seulement un schéma coté.
    p.append("<g>")
    p.append(f"<animateTransform attributeName='transform' type='rotate' "
             f"values='0 {cx} {cy}; 360 {cx} {cy}' dur='10s' repeatCount='indefinite'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='120' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='105' fill='none' stroke='{AXE}' stroke-width='2' stroke-dasharray='9 5'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='86' fill='none' stroke='{FIN}' stroke-width='1.4'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='26' fill='{FOND}' stroke='{TRAIT}' stroke-width='2'/>")
    # quelques dents
    import math as _m
    for k in range(18):
        a1 = _m.radians(k * 20 - 4)
        a2 = _m.radians(k * 20 + 4)
        x1, y1 = cx + 105 * _m.cos(a1), cy + 105 * _m.sin(a1)
        x2, y2 = cx + 120 * _m.cos(a1), cy + 120 * _m.sin(a1)
        x3, y3 = cx + 120 * _m.cos(a2), cy + 120 * _m.sin(a2)
        x4, y4 = cx + 105 * _m.cos(a2), cy + 105 * _m.sin(a2)
        p.append(f"<path d='M{x1:.0f},{y1:.0f} L{x2:.0f},{y2:.0f} L{x3:.0f},{y3:.0f} L{x4:.0f},{y4:.0f}' "
                 f"fill='#e2e8f0' stroke='{TRAIT}' stroke-width='1.4'/>")
    p.append("</g>")
    # cotes
    p.append(f"<line x1='{cx}' y1='{cy}' x2='{cx + 120}' y2='{cy}' stroke='{TRAIT}' stroke-width='1.2'/>")
    p.append(_txt(cx + 60, cy - 8, "da/2", 11, TRAIT, "middle", True))
    p.append(f"<line x1='{cx}' y1='{cy}' x2='{cx - 74}' y2='{cy - 74}' stroke='{AXE}' stroke-width='1.6'/>")
    p.append(_txt(cx - 60, cy - 52, "d/2", 11, AXE, "middle", True))
    p.append(_txt(cx, cy + 148, "d : diamètre primitif — le cercle qui « roule »", 11, AXE, "middle", True))

    p.append(f"<rect x='420' y='60' width='300' height='230' rx='8' fill='#ffffff' stroke='{ALESAGE}' stroke-width='2'/>")
    lignes = [("m", "le module, en mm — normalisé", TRAIT),
              ("Z", "le nombre de dents", TRAIT),
              ("d = m × Z", "diamètre primitif", AXE),
              ("da = d + 2m", "diamètre de tête", TRAIT),
              ("df = d − 2,5m", "diamètre de pied", TRAIT),
              ("p = π × m", "pas : distance entre 2 dents", FIN),
              ("a = m(Z1+Z2)/2", "entraxe des deux roues", ARBRE),
              ("h = 2,25 m", "hauteur totale de dent", FIN)]
    y = 92
    for f, sens, couleur in lignes:
        p.append(_txt(440, y, f, 12, couleur, "start", True))
        p.append(_txt(575, y, sens, 10, FIN))
        y += 26
    p.append(f"<rect x='40' y='320' width='680' height='66' fill='#f0fdf4' stroke='{OK}' rx='6'/>")
    p.append(_txt(56, 343, "Deux roues qui engrènent ont OBLIGATOIREMENT le même module.", 12, TRAIT, "start", True))
    p.append(_txt(56, 363, "Et il faut environ 17 dents minimum : en dessous, l'outil de taillage entame le pied", 12, FIN))
    p.append(_txt(56, 381, "de la dent et l'affaiblit — c'est l'interférence.", 12, FIN))
    return _svg("".join(p), 760, 400)


# ===========================================================================
# 51. LES INSTRUMENTS DE MESURE
# ===========================================================================

def instruments_mesure():
    p = [_txt(40, 26, "À chaque tolérance son instrument — et pas l'inverse :", 13, TRAIT, "start", True)]
    outils = [
        ("Réglet", "0,5 mm", "dégrossir, vérifier une longueur brute", FIN, 0.5),
        ("Pied à coulisse", "0,02 mm", "la cote courante, IT ≥ 0,1 mm", ALESAGE, 0.02),
        ("Micromètre", "0,001 mm", "portées ajustées, H7 et au-delà", OK, 0.001),
        ("Comparateur", "0,01 mm", "battement, planéité, écarts relatifs", ARBRE, 0.01),
        ("Calibre à limites", "—", "série : entre / n'entre pas, sans lecture", ALERTE, 0),
        ("MMT tridimensionnelle", "0,001 mm", "géométrie complète, tolérances GPS", ALESAGE, 0.001),
    ]
    y = 60
    for _i, (nom, prec, usage, couleur, _tol) in enumerate(outils):
        # les 6 instruments s'éclairent l'un après l'autre, du moins précis au plus précis.
        p.append(f"<rect x='50' y='{y}' width='670' height='44' rx='6' fill='#ffffff' stroke='{couleur}' stroke-width='1.5'>"
                 f"<animate attributeName='stroke-width' values='1.5;3;1.5;1.5;1.5;1.5' dur='4.8s' "
                 f"begin='{_i * 0.8}s' repeatCount='indefinite'/></rect>")
        p.append(_txt(68, y + 27, nom, 12, couleur, "start", True))
        p.append(_txt(250, y + 27, prec, 12, TRAIT, "start", True))
        p.append(_txt(345, y + 27, usage, 11, FIN))
        y += 52
    p.append(f"<rect x='40' y='{y + 4}' width='680' height='86' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, y + 27, "RÈGLE DES 10 % : l'incertitude de l'instrument doit rester inférieure au dixième", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 46, "de l'intervalle de tolérance à contrôler.", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 70, "Un IT de 0,02 mm exige donc 0,002 mm d'incertitude : le pied à coulisse est hors jeu.",
                  11, ALERTE, "start", True))
    return _svg("".join(p), 760, y + 100)


# ===========================================================================
# 52. LE GRAFCET
# ===========================================================================

def grafcet_principe():
    p = [_txt(40, 26, "Un GRAFCET décrit un automatisme : des étapes, et ce qui fait passer à la suivante :",
              13, TRAIT, "start", True)]
    etapes = [("0", "Attente", "étape initiale", 70),
              ("1", "Serrer la pièce", "sortir vérin de bridage", 150),
              ("2", "Percer", "descendre la broche", 230),
              ("3", "Desserrer", "rentrer le vérin", 310)]
    x = 150
    for num, nom, action, y in etapes:
        double = " stroke-width='3.5'" if num == "0" else " stroke-width='2'"
        p.append(f"<rect x='{x}' y='{y}' width='54' height='42' fill='#ffffff' stroke='{TRAIT}'{double}/>")
        if num == "0":
            p.append(f"<rect x='{x + 5}' y='{y + 5}' width='44' height='32' fill='none' stroke='{TRAIT}' stroke-width='1.4'/>")
        p.append(_txt(x + 27, y + 27, num, 15, TRAIT, "middle", True))
        p.append(f"<rect x='{x + 90}' y='{y + 4}' width='250' height='34' rx='4' fill='#e2e8f0' stroke='{FIN}'/>")
        p.append(_txt(x + 104, y + 19, nom, 12, TRAIT, "start", True))
        p.append(_txt(x + 104, y + 33, action, 10, FIN))
        p.append(f"<line x1='{x + 54}' y1='{y + 21}' x2='{x + 90}' y2='{y + 21}' stroke='{FIN}' stroke-width='1.2'/>")
        if y < 310:
            p.append(f"<line x1='{x + 27}' y1='{y + 42}' x2='{x + 27}' y2='{y + 80}' stroke='{TRAIT}' stroke-width='1.8'/>")
            p.append(f"<line x1='{x + 12}' y1='{y + 61}' x2='{x + 42}' y2='{y + 61}' stroke='{ALERTE}' stroke-width='2.4'/>")
    trans = [("dcy · pièce présente", 131), ("pièce serrée", 211), ("perçage terminé", 291)]
    for texte, y in trans:
        p.append(_txt(x + 50, y + 5, texte, 11, ALERTE, "start", True))
    p.append(f"<line x1='{x + 27}' y1='352' x2='{x + 27}' y2='380' stroke='{TRAIT}' stroke-width='1.8'/>")
    p.append(f"<line x1='{x + 27}' y1='380' x2='80' y2='380' stroke='{TRAIT}' stroke-width='1.8'/>")
    p.append(f"<line x1='80' y1='380' x2='80' y2='91' stroke='{TRAIT}' stroke-width='1.8'/>")
    p.append(f"<line x1='80' y1='91' x2='{x}' y2='91' stroke='{TRAIT}' stroke-width='1.8'/>")
    # un jeton parcourt le cycle des étapes en boucle : on VOIT l'étape ACTIVE se
    # déplacer, une seule à la fois, jamais deux en même temps.
    p.append(f"<circle r='7' fill='{ALERTE}'>"
             f"<animateMotion dur='6s' repeatCount='indefinite' "
             f"path='M{x + 27},91 L{x + 27},352 L{x + 27},380 L80,380 L80,91 L{x},91'/></circle>")
    p.append(f"<rect x='540' y='60' width='200' height='150' rx='8' fill='#f0fdf4' stroke='{OK}' stroke-width='2'/>")
    p.append(_txt(556, 86, "Deux règles :", 12, TRAIT, "start", True))
    p.append(_txt(556, 110, "1. l'étape au-dessus", 11, FIN))
    p.append(_txt(556, 126, "   doit être ACTIVE", 11, FIN))
    p.append(_txt(556, 152, "2. la réceptivité", 11, FIN))
    p.append(_txt(556, 168, "   doit être VRAIE", 11, FIN))
    p.append(_txt(556, 194, "Alors on avance.", 11, OK, "start", True))
    return _svg("".join(p), 760, 400)


# ===========================================================================
# 52B. LA MÉTHODE DE RÉSOLUTION D'UN EXERCICE (9 ÉTAPES)
# ===========================================================================

def methode_resolution():
    etapes = [
        ("1", "Lire l'énoncé en entier", ALESAGE),
        ("2", "Relever les données", ALESAGE),
        ("3", "Identifier la grandeur cherchée", ALESAGE),
        ("4", "Choisir la formule", AXE),
        ("5", "Convertir les unités", ALERTE),
        ("6", "Poser le calcul", AXE),
        ("7", "Vérifier l'unité du résultat", OK),
        ("8", "Comparer à la valeur admissible", OK),
        ("9", "Conclure en une phrase", OK),
    ]
    p = [_txt(30, 26, "Neuf étapes fixes, toujours dans le même ordre :", 13, TRAIT, "start", True)]
    x, y0, pas, r = 70, 60, 38, 15
    p.append(f"<line x1='{x}' y1='{y0}' x2='{x}' y2='{y0 + pas * (len(etapes) - 1)}' "
             f"stroke='{FIN}' stroke-width='2'/>")
    # un point descend la ligne, étape après étape, sans jamais en sauter une : on VOIT
    # l'ordre imposé.
    p.append(f"<circle r='6' fill='{ALERTE}'>"
             f"<animateMotion dur='{len(etapes) * 0.5}s' repeatCount='indefinite' "
             f"path='M{x},{y0} L{x},{y0 + pas * (len(etapes) - 1)}'/></circle>")
    for i, (num, texte, couleur) in enumerate(etapes):
        y = y0 + i * pas
        p.append(f"<circle cx='{x}' cy='{y}' r='{r}' fill='#ffffff' stroke='{couleur}' "
                  f"stroke-width='2.2'/>")
        p.append(_txt(x, y + 5, num, 13, couleur, "middle", True))
        p.append(_txt(x + 32, y + 5, texte, 13, TRAIT, "start", (i in (4, 8))))
        if i == 4:
            p.append(_txt(x + 32, y + 20, "→ avant le calcul, jamais après", 10, ALERTE, "start"))
        if i == 8:
            p.append(_txt(x + 32, y + 20, "→ jamais laisser un chiffre nu, sans réponse",
                          10, OK, "start"))
    p.append(_txt(x, y0 + pas * (len(etapes) - 1) + 46,
                  "Sauter une étape est la cause la plus fréquente d'erreur — même sur un "
                  "calcul simple.", 11, FIN, "middle"))
    return _svg("".join(p), 500, y0 + pas * (len(etapes) - 1) + 70)


# ===========================================================================
# 53. LE CYCLE DE VIE D'UN PRODUIT
# ===========================================================================

def cycle_de_vie():
    import math as _m
    p = [_txt(40, 26, "L'impact d'un produit ne se joue pas qu'à sa fabrication :", 13, TRAIT, "start", True)]
    cx, cy, r = 235, 205, 115
    phases = [("Matières\npremières", -90, ALESAGE), ("Fabrication", -18, ALESAGE),
              ("Distribution", 54, FIN), ("Utilisation", 126, ALERTE),
              ("Fin de vie", 198, OK)]
    for nom, ang, couleur in phases:
        a = _m.radians(ang)
        x, y = cx + r * _m.cos(a), cy + r * _m.sin(a)
        p.append(f"<circle cx='{x:.0f}' cy='{y:.0f}' r='40' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        parts = nom.split("\n")
        for i, part in enumerate(parts):
            p.append(_txt(x, y + 4 + (i - (len(parts) - 1) / 2) * 13, part, 10, couleur, "middle", True))
    p.append(f"<circle cx='{cx}' cy='{cy}' r='58' fill='none' stroke='{FIN}' stroke-width='1.4' stroke-dasharray='7 5'/>")
    p.append(_txt(cx, cy - 4, "cycle", 12, FIN, "middle", True))
    p.append(_txt(cx, cy + 14, "de vie", 12, FIN, "middle", True))
    # un point parcourt le cercle des cinq phases en boucle : on VOIT que ça recommence.
    p.append(f"<circle r='7' fill='{ALERTE}'>"
             f"<animateMotion dur='6s' repeatCount='indefinite' "
             f"path='M {cx + r},{cy} A {r},{r} 0 1,1 {cx - r},{cy} A {r},{r} 0 1,1 {cx + r},{cy}'/></circle>")
    p.append(f"<rect x='400' y='70' width='320' height='170' rx='8' fill='#ffffff' stroke='{ALERTE}' stroke-width='2'/>")
    p.append(_txt(560, 96, "Où est l'impact ?", 12, ALERTE, "middle", True))
    p.append(_txt(418, 124, "Machine-outil, véhicule, appareil :", 11, TRAIT, "start", True))
    p.append(_txt(418, 144, "80 à 90 % de l'impact vient de la", 11, FIN))
    p.append(_txt(418, 160, "phase d'UTILISATION (énergie).", 11, FIN))
    p.append(_txt(418, 188, "Emballage, mobilier, structure :", 11, TRAIT, "start", True))
    p.append(_txt(418, 208, "l'impact vient surtout de la MATIÈRE", 11, FIN))
    p.append(_txt(418, 224, "et de la fabrication.", 11, FIN))
    p.append(f"<rect x='400' y='255' width='320' height='84' rx='8' fill='#f0fdf4' stroke='{OK}' stroke-width='2'/>")
    p.append(_txt(418, 280, "Conséquence de conception :", 12, TRAIT, "start", True))
    p.append(_txt(418, 302, "alléger une pièce mobile réduit plus", 11, OK, "start", True))
    p.append(_txt(418, 320, "l'impact que changer son matériau.", 11, OK, "start", True))
    return _svg("".join(p), 760, 360)


