# 67. LES QUATRE FAMILLES DE TOLÉRANCES GÉOMÉTRIQUES
# ===========================================================================

def familles_gps():
    p = [_txt(40, 26, "Quatre familles — et une seule question pour les distinguer :", 13, TRAIT, "start", True)]
    p.append(f"<rect x='55' y='52' width='650' height='34' rx='6' fill='#eff6ff' stroke='{ALESAGE}' stroke-width='1.6'/>")
    p.append(_txt(380, 74, "« Ce défaut se juge-t-il tout seul, ou PAR RAPPORT à quelque chose ? »",
                  12, ALESAGE, "middle", True))
    familles = [
        (55, "FORME", "sans référence", ["rectitude", "planéité", "circularité", "cylindricité"],
         "la surface se juge seule", OK),
        (225, "ORIENTATION", "avec référence", ["parallélisme", "perpendicularité", "inclinaison"],
         "un ANGLE par rapport à A", ALESAGE),
        (395, "POSITION", "avec référence", ["localisation", "coaxialité", "symétrie"],
         "un ENDROIT / à A et B", ARBRE),
        (565, "BATTEMENT", "avec référence", ["radial", "axial", "total"],
         "ce que lit un comparateur", ALERTE),
    ]
    for _i, (x0, nom, ref, liste, resume, couleur) in enumerate(familles):
        # les quatre familles s'éclairent l'une après l'autre : on VOIT qu'il y en a
        # exactement quatre, chacune répondant différemment à la même question.
        p.append(f"<rect x='{x0}' y='104' width='140' height='190' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'>"
                 f"<animate attributeName='stroke-width' values='2;3.6;2;2;2;2;2;2' dur='6.4s' "
                 f"begin='{_i * 0.9}s' repeatCount='indefinite'/></rect>")
        p.append(_txt(x0 + 70, 128, nom, 12, couleur, "middle", True))
        p.append(_txt(x0 + 70, 146, ref, 10, FIN, "middle"))
        y = 174
        for item in liste:
            p.append(_txt(x0 + 70, y, item, 10, TRAIT, "middle"))
            y += 20
        p.append(_txt(x0 + 70, 268, resume, 9, couleur, "middle", True))
    p.append(f"<rect x='40' y='310' width='680' height='68' fill='#f0fdf4' stroke='{OK}' rx='6'/>")
    p.append(_txt(56, 333, "Seule la famille FORME se passe de référence : être plan est une propriété de la",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 353, "surface elle-même. Être perpendiculaire, c'est forcément perpendiculaire À QUELQUE", 12, FIN))
    p.append(_txt(56, 371, "CHOSE — d'où la lettre de référence dans le cadre.", 12, FIN))
    return _svg("".join(p), 760, 395)


