# ===========================================================================
# 70. LE MONTAGE COMPLET D'UN ARBRE SUR DEUX ROULEMENTS
# ===========================================================================

def montage_arbre_complet():
    p = [_txt(40, 24, "Les cinq décisions d'un montage de roulements, sur un seul dessin :", 13, TRAIT, "start", True)]
    # carter
    p.append(f"<rect x='70' y='150' width='620' height='24' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(f"<rect x='120' y='95' width='40' height='60' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='1.8'/>")
    p.append(f"<rect x='560' y='95' width='40' height='60' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='1.8'/>")
    # arbre
    p.append(f"<rect x='90' y='118' width='560' height='22' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
    # roulements
    for x, libelle, couleur in ((140, "PALIER FIXE", OK), (580, "PALIER LIBRE", ALESAGE)):
        p.append(f"<rect x='{x - 18}' y='108' width='36' height='42' fill='#ffffff' stroke='{ARBRE}' stroke-width='2'/>")
        p.append(f"<circle cx='{x}' cy='129' r='6' fill='{ARBRE}' opacity='0.5'/>")
        p.append(_txt(x, 88, libelle, 10, couleur, "middle", True))
    # butees palier fixe
    p.append(f"<line x1='122' y1='104' x2='122' y2='154' stroke='{OK}' stroke-width='3'/>")
    p.append(f"<line x1='158' y1='104' x2='158' y2='154' stroke='{OK}' stroke-width='3'/>")
    # palier libre : flèches de coulissement qui s'écartent puis reviennent — on VOIT
    # que ce palier laisse l'arbre libre de se dilater, contrairement au palier fixe.
    p.append(f"<line x1='598' y1='129' x2='632' y2='129' stroke='{ALESAGE}' stroke-width='2'>"
             f"<animateTransform attributeName='transform' type='translate' "
             f"values='0,0; 6,0; 0,0' dur='1.6s' repeatCount='indefinite'/></line>")
    p.append(f"<line x1='562' y1='129' x2='546' y2='129' stroke='{ALESAGE}' stroke-width='2'>"
             f"<animateTransform attributeName='transform' type='translate' "
             f"values='0,0; -6,0; 0,0' dur='1.6s' repeatCount='indefinite'/></line>")
    # joint a levres
    p.append(f"<path d='M636,118 l14,6 l-14,6' fill='none' stroke='{ALERTE}' stroke-width='2'/>")
    p.append(_txt(658, 100, "joint à lèvres", 10, ALERTE, "start", True))
    p.append(_txt(658, 114, "portée Ra 0,8", 9, FIN, "start"))
    decisions = [
        ("1", "quelle bague serrée ?", "charge tournante → bague intérieure : arbre k6, alésage H7", ARBRE),
        ("2", "quel palier fixe ?", "UN SEUL — l'autre doit coulisser pour la dilatation", OK),
        ("3", "quels arrêts axiaux ?", "épaulement d'un côté, anneau élastique de l'autre", TRAIT),
        ("4", "quelle lubrification ?", "graisse au tiers du volume libre, ou roulements 2RS", ALESAGE),
        ("5", "quelle étanchéité ?", "joint à lèvres, lèvre vers l'intérieur, portée Ra 0,8", ALERTE),
    ]
    y = 205
    for _i, (num, question, reponse, couleur) in enumerate(decisions):
        # les 5 décisions s'éclairent l'une après l'autre : on VOIT qu'il y en a
        # exactement cinq à prendre, dans cet ordre, pour un montage complet.
        p.append(f"<circle cx='72' cy='{y - 4}' r='11' fill='{couleur}'>"
                 f"<animate attributeName='r' values='11;14;11;11;11' dur='4s' "
                 f"begin='{_i * 0.9}s' repeatCount='indefinite'/></circle>")
        p.append(_txt(72, y, num, 11, "#ffffff", "middle", True))
        p.append(_txt(92, y, question, 11, couleur, "start", True))
        p.append(_txt(262, y, reponse, 11, FIN))
        y += 30
    p.append(f"<rect x='40' y='350' width='680' height='48' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 372, "Le détail qui tue : le rayon du congé d'épaulement doit être INFÉRIEUR à celui de", 12, TRAIT, "start", True))
    p.append(_txt(56, 390, "la bague — sinon elle porte sur l'arrondi et se monte de travers.", 12, FIN))
    return _svg("".join(p), 760, 415)


# ===========================================================================
# 71. CE QUI TIENT VRAIMENT UN ASSEMBLAGE VISSÉ
# ===========================================================================

def precharge_vissage():
    p = [_txt(40, 24, "Contre-intuitif : ce ne sont pas les vis qui reprennent l'effort.", 13, TRAIT, "start", True)]
    # deux toles + vis
    p.append(f"<rect x='90' y='120' width='300' height='26' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<rect x='90' y='146' width='300' height='26' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<rect x='222' y='96' width='36' height='24' fill='{ARBRE}' opacity='0.5' stroke='{TRAIT}' stroke-width='1.8'/>")
    p.append(f"<rect x='230' y='120' width='20' height='72' fill='{ARBRE}' opacity='0.35' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(f"<rect x='222' y='172' width='36' height='20' fill='{ARBRE}' opacity='0.5' stroke='{TRAIT}' stroke-width='1.8'/>")
    # precharge : fleches de serrage
    # les flèches de précharge s'étirent puis reviennent : on VOIT la vis travailler
    # comme un ressort tendu, en permanence, pas juste au serrage.
    p.append(f"<line x1='240' y1='90' x2='240' y2='60' stroke='{OK}' stroke-width='2.6' marker-end='url(#y1)'>"
             f"<animateTransform attributeName='transform' type='translate' "
             f"values='0,0; 0,-3; 0,0' dur='1.4s' repeatCount='indefinite'/></line>")
    p.append(f"<line x1='240' y1='198' x2='240' y2='228' stroke='{OK}' stroke-width='2.6' marker-end='url(#y1)'>"
             f"<animateTransform attributeName='transform' type='translate' "
             f"values='0,0; 0,3; 0,0' dur='1.4s' repeatCount='indefinite'/></line>")
    p.append("<defs><marker id='y1' markerWidth='9' markerHeight='9' refX='8' refY='4.5' orient='auto'>"
             f"<path d='M0,0 L9,4.5 L0,9 z' fill='{OK}'/></marker></defs>")
    p.append(_txt(258, 62, "la vis est ÉTIRÉE : elle est un ressort tendu", 11, OK, "start", True))
    # pression de contact — les repères pulsent ensemble : on VOIT les tôles plaquées.
    for x in range(150, 340, 22):
        p.append(f"<line x1='{x}' y1='138' x2='{x}' y2='154' stroke='{ALESAGE}' stroke-width='2.4'>"
                 f"<animate attributeName='stroke-width' values='2.4;3.6;2.4' dur='1.4s' repeatCount='indefinite'/></line>")
    p.append(_txt(240, 250, "les tôles sont PLAQUÉES l'une contre l'autre", 11, ALESAGE, "middle", True))
    # effort transmis par adherence
    p.append(f"<line x1='60' y1='133' x2='86' y2='133' stroke='{ALERTE}' stroke-width='2.4'/>")
    p.append(f"<line x1='394' y1='159' x2='420' y2='159' stroke='{ALERTE}' stroke-width='2.4'/>")
    p.append(_txt(240, 268, "et c'est l'ADHÉRENCE entre elles qui transmet l'effort", 11, ALERTE, "middle", True))
    # encadre
    p.append(f"<rect x='450' y='96' width='270' height='160' rx='8' fill='#ffffff' stroke='{ALESAGE}' stroke-width='2'/>")
    p.append(_txt(585, 120, "Trois conséquences", 12, ALESAGE, "middle", True))
    cons = [("un serrage insuffisant", "= 1re cause de desserrage"),
            ("on serre à la clé", "dynamométrique, au couple de la classe"),
            ("la rondelle plate", "ne freine RIEN : elle répartit")]
    y = 148
    for a, b in cons:
        p.append(_txt(468, y, "• " + a, 11, TRAIT, "start", True))
        p.append(_txt(480, y + 15, b, 10, FIN))
        y += 38
    p.append(f"<rect x='40' y='288' width='680' height='68' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 311, "Si les vis travaillaient en cisaillement, il faudrait des trous ajustés — or ils sont",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 331, "toujours percés avec du jeu. C'est la preuve que l'effort passe par le frottement", 12, FIN))
    p.append(_txt(56, 349, "entre les pièces, et non par la tige des vis.", 12, FIN))
    return _svg("".join(p), 760, 375)


# ===========================================================================
# 72. L'ARC-BOUTEMENT D'UN GUIDAGE
# ===========================================================================

def arc_boutement():
    p = [_txt(40, 24, "Pourquoi un tiroir se coince quand on le tire d'un seul côté :", 13, TRAIT, "start", True)]
    for x0, titre, Lg, verdict, couleur in ((55, "GUIDAGE TROP COURT", 60, "il se coince", ALERTE),
                                            (400, "GUIDAGE SUFFISANT", 150, "il coulisse", OK)):
        p.append(f"<rect x='{x0}' y='55' width='305' height='215' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        p.append(_txt(x0 + 152, 80, titre, 12, couleur, "middle", True))
        # rail
        p.append(f"<rect x='{x0 + 30}' y='120' width='245' height='12' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='1.4'/>")
        p.append(f"<rect x='{x0 + 30}' y='180' width='245' height='12' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='1.4'/>")
        # chariot — il coulisse librement s'il est assez long, il tente de bouger puis
        # se coince (légère rotation) s'il est trop court : on VOIT l'arc-boutement.
        if Lg == 60:
            p.append(f"<rect x='{x0 + 50}' y='132' width='{Lg}' height='48' fill='#e2e8f0' stroke='{couleur}' stroke-width='2'>"
                     f"<animateTransform attributeName='transform' type='rotate' "
                     f"values='0 {x0 + 80} {156}; 3 {x0 + 80} {156}; 0 {x0 + 80} {156}' dur='1.4s' "
                     f"repeatCount='indefinite'/></rect>")
        else:
            p.append(f"<rect x='{x0 + 50}' y='132' width='{Lg}' height='48' fill='#e2e8f0' stroke='{couleur}' stroke-width='2'>"
                     f"<animateTransform attributeName='transform' type='translate' "
                     f"values='0,0; 30,0; 0,0' dur='2.4s' repeatCount='indefinite'/></rect>")
        p.append(f"<line x1='{x0 + 50}' y1='205' x2='{x0 + 50 + Lg}' y2='205' stroke='{couleur}' stroke-width='1.4'/>")
        p.append(_txt(x0 + 50 + Lg / 2, 220, "longueur de guidage", 9, couleur, "middle"))
        # effort excentre
        p.append(f"<line x1='{x0 + 250}' y1='156' x2='{x0 + 200}' y2='156' stroke='{ARBRE}' stroke-width='2.4' marker-end='url(#z1)'/>")
        p.append("<defs><marker id='z1' markerWidth='9' markerHeight='9' refX='8' refY='4.5' orient='auto'>"
                 f"<path d='M0,0 L9,4.5 L0,9 z' fill='{ARBRE}'/></marker></defs>")
        p.append(_txt(x0 + 255, 148, "F", 12, ARBRE, "start", True))
        if Lg == 60:
            p.append(f"<circle cx='{x0 + 52}' cy='134' r='6' fill='{ALERTE}' opacity='0.6'>"
                     f"<animate attributeName='r' values='6;9;6' dur='1.4s' repeatCount='indefinite'/></circle>")
            p.append(f"<circle cx='{x0 + 108}' cy='178' r='6' fill='{ALERTE}' opacity='0.6'>"
                     f"<animate attributeName='r' values='6;9;6' dur='1.4s' repeatCount='indefinite'/></circle>")
            p.append(_txt(x0 + 152, 246, "les 2 points de contact bloquent", 10, ALERTE, "middle", True))
        else:
            p.append(_txt(x0 + 152, 246, "l'effort se répartit sur la longueur", 10, OK, "middle", True))
        p.append(_txt(x0 + 152, 262, verdict, 11, couleur, "middle", True))
    p.append(f"<rect x='40' y='288' width='680' height='68' fill='#f0fdf4' stroke='{OK}' rx='6'/>")
    p.append(_txt(56, 311, "Règle : longueur de guidage ≈ 1,5 à 2 fois la course.", 12, TRAIT, "start", True))
    p.append(_txt(56, 331, "Un guidage trop court se coince quel que soit le soin d'usinage : c'est une question", 12, FIN))
    p.append(_txt(56, 349, "de géométrie et de frottement, pas de précision.", 12, FIN))
    return _svg("".join(p), 760, 375)


# ===========================================================================
# 73. CARACTÉRISER UNE FONCTION : CRITÈRE, NIVEAU, FLEXIBILITÉ
# ===========================================================================

def caracteriser_fonction():
    p = [_txt(40, 24, "Une exigence vague ne peut être ni vérifiée, ni contestée, ni chiffrée :", 13, TRAIT, "start", True)]
    # avant
    p.append(f"<rect x='55' y='52' width='300' height='96' rx='8' fill='#fef2f2' stroke='{ALERTE}' stroke-width='2'/>")
    p.append(_txt(205, 76, "CE QUE DIT LE CLIENT", 11, ALERTE, "middle", True))
    p.append(_txt(205, 104, "« le carter doit être solide", 12, TRAIT, "middle"))
    p.append(_txt(205, 124, "et facile à nettoyer »", 12, TRAIT, "middle"))
    # fleche — elle pulse en boucle : on VOIT la transformation de la phrase vague vers
    # l'exigence vérifiable.
    p.append(f"<line x1='368' y1='100' x2='408' y2='100' stroke='{FIN}' stroke-width='2' marker-end='url(#aa1)' "
             f"stroke-dasharray='6 4'><animate attributeName='stroke-dashoffset' values='0;-20' "
             f"dur='1.4s' repeatCount='indefinite'/></line>")
    p.append("<defs><marker id='aa1' markerWidth='9' markerHeight='9' refX='8' refY='4.5' orient='auto'>"
             f"<path d='M0,0 L9,4.5 L0,9 z' fill='{FIN}'/></marker></defs>")
    # apres
    p.append(f"<rect x='420' y='52' width='300' height='96' rx='8' fill='#f0fdf4' stroke='{OK}' stroke-width='2'/>")
    p.append(_txt(570, 76, "CE QU'ON ÉCRIT", 11, OK, "middle", True))
    p.append(_txt(570, 100, "FC1 résister aux chocs", 11, TRAIT, "middle", True))
    p.append(_txt(570, 122, "FC2 permettre le nettoyage", 11, TRAIT, "middle", True))
    # tableau des 3 elements
    colonnes = [(70, "CRITÈRE", "la grandeur observée", "énergie de choc", ALESAGE),
                (295, "NIVEAU", "la valeur à atteindre", "5 J sans déformation", ARBRE),
                (520, "FLEXIBILITÉ", "ce qui est négociable", "F0 — impératif", OK)]
    for _i, (x, nom, quoi, exemple, couleur) in enumerate(colonnes):
        # les trois éléments s'éclairent l'un après l'autre : on VOIT qu'il en faut
        # exactement trois pour qu'une exigence soit vérifiable.
        p.append(f"<rect x='{x}' y='180' width='195' height='110' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'>"
                 f"<animate attributeName='stroke-width' values='2;3.6;2;2;2;2' dur='3.6s' "
                 f"begin='{_i * 1.1}s' repeatCount='indefinite'/></rect>")
        p.append(_txt(x + 97, 206, nom, 12, couleur, "middle", True))
        p.append(_txt(x + 97, 228, quoi, 10, FIN, "middle"))
        p.append(f"<line x1='{x + 30}' y1='242' x2='{x + 165}' y2='242' stroke='{FIN}' stroke-width='0.8'/>")
        p.append(_txt(x + 97, 266, exemple, 11, couleur, "middle", True))
    p.append(f"<rect x='40' y='308' width='680' height='66' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 330, "F0 impératif · F1 peu négociable · F2 négociable · F3 simple souhait", 12, TRAIT, "start", True))
    p.append(_txt(56, 352, "C'est ce tableau qui servira à VALIDER le produit en fin de projet : on reprend chaque", 12, FIN))
    p.append(_txt(56, 368, "ligne, on mesure, on coche. Une exigence non chiffrée est incochable.", 12, FIN))
    return _svg("".join(p), 760, 392)


# ===========================================================================
# 74. LIRE UN PLAN INCONNU EN SIX ÉTAPES
# ===========================================================================

def lire_plan_methode():
    p = [_txt(40, 24, "Face à un plan qu'on découvre, on ne commence pas par les cotes :", 13, TRAIT, "start", True)]
    etapes = [
        ("1", "Le CARTOUCHE", "titre, échelle, matière, indice — et surtout le symbole de projection", ALERTE),
        ("2", "La vue de FACE", "repérer la vue principale et les vues qui l'accompagnent", ALESAGE),
        ("3", "Les COUPES", "trouver où passent les plans de coupe, sur quelle vue", ALESAGE),
        ("4", "Une FORME à la fois", "suivre un trou, un épaulement, d'une vue à l'autre", TRAIT),
        ("5", "Les cotes TOLÉRANCÉES", "elles désignent les surfaces qui travaillent", OK),
        ("6", "Les états de surface et le GPS", "ils disent où est la précision, et pourquoi", OK),
    ]
    y = 60
    for _i, (num, titre, detail, couleur) in enumerate(etapes):
        # les 6 étapes s'éclairent dans l'ordre : on VOIT la méthode se dérouler, jamais
        # en commençant par les cotes.
        p.append(f"<rect x='55' y='{y}' width='650' height='44' rx='6' fill='#ffffff' stroke='{couleur}' stroke-width='1.5'/>")
        p.append(f"<circle cx='84' cy='{y + 22}' r='14' fill='{couleur}'>"
                 f"<animate attributeName='r' values='14;17;14;14;14;14;14;14;14;14;14;14' dur='7.2s' "
                 f"begin='{_i * 1.1}s' repeatCount='indefinite'/></circle>")
        p.append(_txt(84, y + 27, num, 13, "#ffffff", "middle", True))
        p.append(_txt(112, y + 19, titre, 12, TRAIT, "start", True))
        p.append(_txt(112, y + 35, detail, 10, FIN))
        y += 50
    p.append(f"<rect x='40' y='{y + 8}' width='680' height='68' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, y + 31, "L'étape 1 n'est pas une formalité : un plan américain lu comme un plan européen", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 51, "donne une pièce EN MIROIR. Le symbole de projection se vérifie AVANT tout le reste.", 12, FIN))
    return _svg("".join(p), 760, y + 92)


# ===========================================================================
# 75. COTER EN CHAÎNE OU DEPUIS UNE RÉFÉRENCE
# ===========================================================================

def cotation_reference():
    p = [_txt(40, 24, "Quatre trous à percer, deux façons de les coter — et un seul résultat correct :",
              12, TRAIT, "start", True)]
    for x0, titre, mode, couleur, verdict in ((55, "EN CHAÎNE", "chaine", ALERTE, "les erreurs S'ADDITIONNENT"),
                                              (400, "DEPUIS UNE RÉFÉRENCE", "ref", OK, "chaque trou est indépendant")):
        p.append(f"<rect x='{x0}' y='52' width='305' height='215' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        p.append(_txt(x0 + 152, 76, titre, 12, couleur, "middle", True))
        # plaque
        p.append(f"<rect x='{x0 + 30}' y='96' width='250' height='46' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='1.8'/>")
        trous = [x0 + 60, x0 + 120, x0 + 180, x0 + 240]
        for tx in trous:
            p.append(f"<circle cx='{tx}' cy='119' r='7' fill='{FOND}' stroke='{TRAIT}' stroke-width='1.6'/>")
        if mode == "chaine":
            # les cotes apparaissent l'une après l'autre, comme l'erreur qui s'accumule
            # de trou en trou : on VOIT le cumul se construire.
            y = 160
            for i in range(4):
                x1 = x0 + 30 if i == 0 else trous[i - 1]
                x2 = trous[i]
                p.append(f"<g opacity='0'><animate attributeName='opacity' from='0' to='1' "
                         f"dur='.4s' begin='{i * 0.5}s' fill='freeze'/>"
                         f"<line x1='{x1}' y1='{y}' x2='{x2}' y2='{y}' stroke='{couleur}' stroke-width='1.4'/>"
                         f"{_txt((x1 + x2) / 2, y - 5, '±0,2', 9, couleur, 'middle')}</g>")
            p.append(_txt(x0 + 152, 196, "sur le 4e trou : ±0,8 cumulé", 11, ALERTE, "middle", True))
        else:
            # les quatre cotes apparaissent ENSEMBLE, toutes depuis la même référence :
            # on VOIT qu'aucune ne dépend d'une autre.
            y = 156
            p.append("<g opacity='0'><animate attributeName='opacity' from='0' to='1' "
                     "dur='.4s' begin='2s' fill='freeze'/>")
            for i, tx in enumerate(trous):
                p.append(f"<line x1='{x0 + 30}' y1='{y}' x2='{tx}' y2='{y}' stroke='{couleur}' stroke-width='1.4'/>")
                p.append(_txt(tx + 4, y - 4, "±0,2", 9, couleur, "start"))
                y += 13
            p.append("</g>")
            p.append(f"<line x1='{x0 + 30}' y1='142' x2='{x0 + 30}' y2='215' stroke='{OK}' stroke-width='2'/>")
            p.append(_txt(x0 + 152, 232, "sur le 4e trou : ±0,2 seulement", 11, OK, "middle", True))
        p.append(_txt(x0 + 152, 252, verdict, 11, couleur, "middle", True))
    p.append(f"<rect x='40' y='285' width='680' height='68' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 308, "Pour tout ce qui doit s'assembler avec l'existant — trous de fixation, entraxes —",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 328, "on cote TOUJOURS depuis une référence unique. La cotation en chaîne ne s'emploie", 12, FIN))
    p.append(_txt(56, 346, "que lorsque c'est l'écart entre deux éléments voisins qui compte.", 12, FIN))
    return _svg("".join(p), 760, 372)


