# 77. CHOISIR UN MATÉRIAU : LE BON ORDRE DES QUESTIONS
# ===========================================================================

def arbre_choix_materiau():
    p = [_txt(40, 24, "La première question n'est pas « quel matériau ? » mais « qu'est-ce qui décide ? »",
              12, TRAIT, "start", True)]
    p.append(f"<rect x='190' y='48' width='380' height='40' rx='8' fill='#eff6ff' stroke='{ALESAGE}' stroke-width='2'/>")
    p.append(_txt(380, 73, "La pièce doit-elle RÉSISTER ou ne pas PLIER ?", 12, ALESAGE, "middle", True))
    # deux branches
    p.append(f"<line x1='300' y1='88' x2='200' y2='120' stroke='{ARBRE}' stroke-width='2'/>")
    p.append(f"<line x1='460' y1='88' x2='560' y2='120' stroke='{OK}' stroke-width='2'/>")
    branches = [
        (55, "RÉSISTER", "on joue sur Re, donc sur la NUANCE", ARBRE,
         ["S235 → 235 MPa", "C45 traité → 600 MPa", "42CrMo4 → 750 MPa"]),
        (400, "NE PAS PLIER", "on joue sur I, donc sur la FORME", OK,
         ["nervures, profil creux", "augmenter la hauteur", "raccourcir la portée"]),
    ]
    for _i, (x0, titre, sous, couleur, items) in enumerate(branches):
        # les deux branches s'éclairent en alternance : on VOIT que c'est un choix,
        # pas une liste — RÉSISTER ou NE PAS PLIER, jamais les deux à la fois.
        p.append(f"<rect x='{x0}' y='120' width='300' height='130' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'>"
                 f"<animate attributeName='stroke-width' values='2;4;2;2' dur='3.2s' begin='{_i * 1.6}s' "
                 f"repeatCount='indefinite'/></rect>")
        p.append(_txt(x0 + 150, 145, titre, 12, couleur, "middle", True))
        p.append(_txt(x0 + 150, 165, sous, 10, FIN, "middle"))
        y = 194
        for it in items:
            p.append(_txt(x0 + 150, y, it, 11, TRAIT, "middle"))
            y += 20
    p.append(f"<rect x='55' y='266' width='645' height='36' rx='6' fill='#fef2f2' stroke='{ALERTE}'/>")
    p.append(_txt(378, 289, "Changer de nuance ne change RIEN à la flèche : E est identique pour tous les aciers.",
                  12, ALERTE, "middle", True))
    suites = ["soudée ? → S235, S355, C22", "à tremper ? → au moins 0,3 % de carbone",
              "milieu humide ? → inox ou protection", "masse critique ? → alu, mais plus épais"]
    y = 326
    for s_ in suites:
        p.append(f"<circle cx='72' cy='{y - 4}' r='4' fill='{ALESAGE}'/>")
        p.append(_txt(88, y, s_, 11, TRAIT))
        y += 21
    p.append(_txt(420, 326, "Et toujours en dernier :", 11, FIN, "start", True))
    p.append(_txt(420, 348, "quelle série, quel budget,", 11, FIN, "start"))
    p.append(_txt(420, 368, "quelle disponibilité locale ?", 11, FIN, "start"))
    return _svg("".join(p), 760, 410)


