# 78. LA GAMME D'UNE PIÈCE TRAITÉE
# ===========================================================================

def gamme_traitement():
    p = [_txt(40, 24, "Un pignon, de la barre brute à la pièce finie — et pourquoi cet ordre :",
              13, TRAIT, "start", True)]
    etapes = [
        ("Barre 16MnCr5", "acier à bas carbone, prévu pour être cémenté", FIN),
        ("Tournage d'ébauche", "on laisse 0,3 mm de surépaisseur", ALESAGE),
        ("Taillage de la denture", "avant traitement : la matière est encore tendre", ALESAGE),
        ("CÉMENTATION + TREMPE", "la peau durcit, le cœur reste tenace — ET ÇA DÉFORME", ALERTE),
        ("REVENU", "on récupère la ténacité perdue à la trempe", ALERTE),
        ("Rectification des portées", "on rattrape les déformations et on tient les cotes", OK),
        ("Contrôle", "dureté superficielle, profondeur cémentée, géométrie", TRAIT),
    ]
    y = 56
    for i, (titre, detail, couleur) in enumerate(etapes):
        # les étapes s'éclairent dans l'ordre : ÉBAUCHE → TRAITEMENT → FINITION,
        # un ordre qu'on ne peut pas inverser.
        p.append(f"<rect x='60' y='{y}' width='640' height='40' rx='6' fill='#ffffff' stroke='{couleur}' stroke-width='1.5'>"
                 f"<animate attributeName='stroke-width' values='1.5;3.4;1.5;1.5;1.5;1.5;1.5' dur='7s' "
                 f"begin='{i}s' repeatCount='indefinite'/></rect>")
        p.append(f"<circle cx='88' cy='{y + 20}' r='13' fill='{couleur}' opacity='0.8'/>")
        p.append(_txt(88, y + 25, str((i + 1) * 10), 10, "#ffffff", "middle", True))
        p.append(_txt(116, y + 17, titre, 12, TRAIT, "start", True))
        p.append(_txt(116, y + 33, detail, 10, FIN))
        y += 46
    p.append(f"<rect x='40' y='{y + 6}' width='680' height='86' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, y + 29, "LA RÈGLE QUI COMMANDE TOUT : ÉBAUCHE → TRAITEMENT → FINITION.", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 51, "Une trempe déforme de plusieurs dixièmes. Usiner à la cote avant, c'est jeter la pièce ;", 12, FIN))
    p.append(_txt(56, y + 69, "usiner tout après, c'est user les outils sur une matière devenue très dure.", 12, FIN))
    return _svg("".join(p), 760, y + 110)


# ===========================================================================
# 79. LES CONTRAINTES D'ESQUISSE
# ===========================================================================

def contraintes_esquisse():
    p = [_txt(40, 24, "On contraint d'abord par la GÉOMÉTRIE, on cote seulement ce qui reste :",
              12, TRAIT, "start", True)]
    contraintes = [
        ("coïncidence", "deux points au même endroit", ALESAGE),
        ("horizontale / verticale", "une ligne alignée sur un axe", ALESAGE),
        ("parallèle / perpendiculaire", "deux lignes liées entre elles", ALESAGE),
        ("tangence", "un arc raccordé sans cassure", OK),
        ("**symétrie**", "deux entités de part et d'autre d'un axe", ARBRE),
        ("égalité", "deux longueurs ou rayons identiques", OK),
        ("concentricité", "deux cercles de même centre", OK),
        ("fixe", "l'entité ne bougera plus du tout", ALERTE),
    ]
    y = 56
    for _i, (nom, detail, couleur) in enumerate(contraintes):
        # les 8 contraintes s'éclairent l'une après l'autre : on VOIT qu'il y a un vrai
        # catalogue à connaître, pas une seule recette.
        p.append(f"<rect x='55' y='{y}' width='400' height='32' rx='5' fill='#ffffff' stroke='{couleur}' stroke-width='1.3'>"
                 f"<animate attributeName='stroke-width' values='1.3;2.6;1.3;1.3;1.3;1.3;1.3;1.3' dur='6.4s' "
                 f"begin='{_i * 0.8}s' repeatCount='indefinite'/></rect>")
        p.append(_txt(72, y + 21, nom.replace("**", ""), 11, couleur, "start", True))
        p.append(_txt(240, y + 21, detail, 10, FIN))
        y += 38
    # encadre intention
    p.append(f"<rect x='475' y='56' width='245' height='170' rx='8' fill='#f0fdf4' stroke='{OK}' stroke-width='2'/>")
    p.append(_txt(597, 80, "L'intention de conception", 12, OK, "middle", True))
    p.append(_txt(492, 108, "Un trou au centre d'une plaque :", 10, TRAIT, "start", True))
    p.append(_txt(492, 132, "✗ deux cotes depuis les bords", 10, ALERTE, "start", True))
    p.append(_txt(504, 148, "→ il se décale si on change", 9, FIN))
    p.append(_txt(504, 162, "   la largeur", 9, FIN))
    p.append(_txt(492, 186, "✓ une contrainte de symétrie", 10, OK, "start", True))
    p.append(_txt(504, 202, "→ il reste au centre, toujours", 9, FIN))
    p.append(f"<rect x='40' y='{y + 6}' width='680' height='68' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, y + 29, "Les contraintes géométriques ne coûtent rien, elles sont robustes, et elles portent",
                  12, TRAIT, "start", True))
    p.append(_txt(56, y + 49, "l'INTENTION. Un débutant cote tout : il obtient quinze cotes là où une symétrie", 12, FIN))
    p.append(_txt(56, y + 67, "et deux cotes suffisaient.", 12, FIN))
    return _svg("".join(p), 760, y + 92)


