def chaine_numerique():
    p = [_txt(40, 24, "Un même modèle 3D alimente toute la chaîne — chacun reçoit ce dont il a besoin :",
              12, TRAIT, "start", True)]
    cx, cy = 380, 120
    p.append(f"<rect x='{cx - 90}' y='{cy - 32}' width='180' height='64' rx='8' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2.5'/>")
    p.append(_txt(cx, cy - 6, "MODÈLE 3D", 13, TRAIT, "middle", True))
    p.append(_txt(cx, cy + 14, "paramétré, robuste", 10, FIN, "middle"))
    destinations = [
        (70, 250, "PDF du plan coté", "l'atelier, l'archivage", "c'est LUI qui fait foi", ALERTE),
        (250, 250, "STEP", "un autre bureau d'études", "géométrie exacte", ALESAGE),
        (430, 250, "DXF à plat", "la découpe laser", "tôlerie", ARBRE),
        (610, 250, "STL", "l'impression 3D", "maillage, non modifiable", OK),
    ]
    for _i, (x, y, titre, qui, note, couleur) in enumerate(destinations):
        # les données défilent du modèle vers chaque format : on VOIT la chaîne
        # alimenter les 4 métiers en même temps, depuis une source unique.
        p.append(f"<line x1='{cx}' y1='{cy + 32}' x2='{x + 60}' y2='{y - 8}' stroke='{couleur}' stroke-width='1.6' "
                 f"stroke-dasharray='6 4'><animate attributeName='stroke-dashoffset' values='0;-20' "
                 f"dur='1.2s' begin='{_i * 0.15}s' repeatCount='indefinite'/></line>")
        p.append(f"<rect x='{x}' y='{y}' width='120' height='74' rx='7' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        p.append(_txt(x + 60, y + 24, titre, 11, couleur, "middle", True))
        p.append(_txt(x + 60, y + 44, qui, 9, TRAIT, "middle"))
        p.append(_txt(x + 60, y + 62, note, 9, FIN, "middle"))
    p.append(f"<rect x='40' y='350' width='680' height='68' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 373, "La 3D montre, le PLAN COTÉ engage. Le modèle ne contient ni tolérances, ni états",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 393, "de surface, ni matière, ni indice de révision. En cas de litige avec un fournisseur,", 12, FIN))
    p.append(_txt(56, 411, "c'est le plan qu'on ressort — jamais le fichier 3D.", 12, FIN))
    return _svg("".join(p), 760, 435)


