# 79. L'INTENTION DE CONCEPTION
# ===========================================================================

def intention_conception():
    p = [_txt(40, 24, "La même plaque, un trou au centre — deux façons de le dire au logiciel :",
              13, TRAIT, "start", True)]
    for x0, titre, couleur, methode, apres, verdict in (
            (55, "COTÉ DEPUIS LES BORDS", ALERTE, ["60", "40"], "le trou n'est plus au centre",
             "il faut corriger à la main"),
            (400, "CONTRAINT PAR SYMÉTRIE", OK, ["symétrie", "symétrie"], "le trou reste au centre",
             "le modèle a compris l'intention")):
        p.append(f"<rect x='{x0}' y='50' width='305' height='268' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        p.append(_txt(x0 + 152, 74, titre, 12, couleur, "middle", True))
        # avant
        p.append(_txt(x0 + 152, 96, "au départ", 10, FIN, "middle"))
        p.append(f"<rect x='{x0 + 62}' y='104' width='120' height='60' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='1.6'/>")
        p.append(f"<circle cx='{x0 + 122}' cy='134' r='11' fill='{FOND}' stroke='{TRAIT}' stroke-width='1.6'/>")
        if couleur == ALERTE:
            p.append(f"<line x1='{x0 + 62}' y1='176' x2='{x0 + 122}' y2='176' stroke='{couleur}' stroke-width='1.2'/>")
            p.append(_txt(x0 + 92, 172, "60", 10, couleur, "middle"))
        else:
            p.append(f"<line x1='{x0 + 122}' y1='98' x2='{x0 + 122}' y2='172' stroke='{AXE}' stroke-width='1.2' stroke-dasharray='5 4'/>")
            p.append(_txt(x0 + 152, 176, "symétrie / axe", 10, couleur, "middle", True))
        # apres modification
        p.append(_txt(x0 + 152, 202, "on élargit la plaque de 120 à 180", 10, FIN, "middle"))
        p.append(f"<rect x='{x0 + 42}' y='212' width='180' height='58' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='1.6'/>")
        cxt = x0 + 102 if couleur == ALERTE else x0 + 132
        if couleur == ALERTE:
            # le trou décalé dérive : il ne s'est pas replacé tout seul.
            p.append(f"<circle cx='{cxt}' cy='241' r='11' fill='{FOND}' stroke='{couleur}' stroke-width='2'>"
                     f"<animateTransform attributeName='transform' type='translate' "
                     f"values='0,0; 3,2; -2,1; 0,0' dur='2.6s' repeatCount='indefinite'/></circle>")
        else:
            # le trou contraint reste stable, il respire juste sur place.
            p.append(f"<circle cx='{cxt}' cy='241' r='11' fill='{FOND}' stroke='{couleur}' stroke-width='2'>"
                     f"<animate attributeName='r' values='11;13;11' dur='2.6s' repeatCount='indefinite'/></circle>")
        p.append(_txt(x0 + 152, 306, verdict, 11, couleur, "middle", True))
        p.append(_txt(x0 + 152, 288, apres, 10, couleur, "middle"))
    p.append(f"<rect x='40' y='334' width='680' height='68' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 357, "L'INTENTION DE CONCEPTION : le modèle doit réagir aux modifications comme la",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 377, "pièce réelle devrait le faire. Une contrainte géométrique porte cette intention ;", 12, FIN))
    p.append(_txt(56, 395, "une cote ne porte qu'un chiffre.", 12, FIN))
    return _svg("".join(p), 760, 420)


# ===========================================================================
# 82. LES TROIS TEMPS D'UNE MÉTHODE
# ===========================================================================

def trois_temps_methode(titre_avant="AVANT de calculer", titre_pendant="PENDANT le calcul",
                        titre_apres="APRÈS le résultat"):
    p = [_txt(40, 24, "Le même réflexe, quel que soit l'exercice :", 13, TRAIT, "start", True)]
    temps = [(55, titre_avant, ALESAGE), (285, titre_pendant, ARBRE), (515, titre_apres, OK)]
    for _i, (x0, titre, couleur) in enumerate(temps):
        # les trois temps s'éclairent dans l'ordre : avant, pendant, après — jamais
        # dans un autre ordre.
        p.append(f"<rect x='{x0}' y='55' width='200' height='40' rx='8' fill='{couleur}'>"
                 f"<animate attributeName='opacity' values='0.6;1;0.6;0.6;0.6' dur='3.6s' "
                 f"begin='{_i * 0.8}s' repeatCount='indefinite'/></rect>")
        p.append(_txt(x0 + 100, 80, titre, 12, "#ffffff", "middle", True))
    for x0 in (255, 485):
        p.append(f"<path d='M{x0},75 l24,0' stroke='{FIN}' stroke-width='2.4' marker-end='url(#zz)' "
                 f"stroke-dasharray='6 4'><animate attributeName='stroke-dashoffset' values='0;-20' "
                 f"dur='1s' repeatCount='indefinite'/></path>")
    p.append("<defs><marker id='zz' markerWidth='9' markerHeight='9' refX='8' refY='4.5' orient='auto'>"
             f"<path d='M0,0 L9,4.5 L0,9 z' fill='{FIN}'/></marker></defs>")
    p.append(f"<rect x='40' y='115' width='680' height='70' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 138, "La plupart des points perdus ne viennent pas d'un mauvais calcul :", 12, TRAIT, "start", True))
    p.append(_txt(56, 158, "ils viennent d'une étape sautée, avant ou après. Le calcul lui-même est", 12, FIN))
    p.append(_txt(56, 176, "souvent la partie la plus facile.", 12, FIN))
    return _svg("".join(p), 760, 205)


# ===========================================================================
# 83. SCHÉMA DU SYSTÈME — POSTE DE BRIDAGE (étude de cas 14.1)
# ===========================================================================

def schema_bridage_etude_cas():
    p = [_txt(40, 24, "Le système complet de l'étude de cas, avec les cotes de l'énoncé :",
              13, TRAIT, "start", True)]
    # bati
    p.append(f"<rect x='60' y='250' width='640' height='20' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(_txt(72, 282, "bâti", 10, FIN, "start"))
    # pivot du levier
    px, py = 360, 200
    p.append(f"<circle cx='{px}' cy='{py}' r='7' fill='#ffffff' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<path d='M{px - 12},{py + 10} L{px},{py - 4} L{px + 12},{py + 10} Z' fill='none' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(_txt(px, 178, "axe Ø10", 10, TRAIT, "middle"))
    # levier : de 40mm vers le verin (gauche-bas), a 65mm vers la piece (droite)
    vx, vy = px - 56, py + 44
    sx, sy = px + 65, py - 6
    # le levier bascule légèrement autour de son axe : on VOIT le rapport de bras agir.
    p.append(f"<g><animateTransform attributeName='transform' type='rotate' "
             f"values='-3 {px} {py};3 {px} {py};-3 {px} {py}' dur='2.6s' repeatCount='indefinite'/>"
             f"<line x1='{vx}' y1='{vy}' x2='{sx}' y2='{sy}' stroke='{TRAIT}' stroke-width='7' stroke-linecap='round'/>"
             f"<line x1='{px}' y1='{py}' x2='{vx}' y2='{vy}' stroke='{ALESAGE}' stroke-width='1.2' stroke-dasharray='4 3'/>"
             f"<line x1='{px}' y1='{py}' x2='{sx}' y2='{sy}' stroke='{ARBRE}' stroke-width='1.2' stroke-dasharray='4 3'/></g>")
    p.append(_txt((px + vx) / 2 - 18, (py + vy) / 2 + 6, "40 mm", 11, ALESAGE, "end", True))
    p.append(_txt((px + sx) / 2, (py + sy) / 2 - 12, "65 mm", 11, ARBRE, "middle", True))
    # verin, decale a gauche pour ne pas croiser les cotes
    p.append(f"<rect x='{vx - 110}' y='{vy - 12}' width='55' height='24' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='1.8'/>")
    p.append(f"<line x1='{vx - 55}' y1='{vy}' x2='{vx}' y2='{vy}' stroke='{TRAIT}' stroke-width='5'/>")
    p.append(_txt(vx - 115, vy - 20, "vérin Ø63", 10, TRAIT, "start", True))
    p.append(f"<circle cx='{vx}' cy='{vy}' r='5' fill='#ffffff' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(f"<line x1='{vx - 110}' y1='{vy}' x2='{vx - 110}' y2='250' stroke='{TRAIT}' stroke-width='1.4'/>")
    # piece serree
    p.append(f"<rect x='{sx - 5}' y='{sy - 46}' width='70' height='22' fill='{OK}' opacity='0.28' stroke='{OK}' stroke-width='1.8'/>")
    p.append(_txt(sx + 30, sy - 52, "pièce (alu anodisé)", 10, OK, "middle", True))
    p.append(f"<circle cx='{sx}' cy='{sy}' r='5' fill='#ffffff' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(f"<line x1='{sx}' y1='{sy - 24}' x2='{sx}' y2='{sy}' stroke='{OK}' stroke-width='3'/>")
    p.append(f"<line x1='{sx}' y1='{sy - 24}' x2='{sx - 9}' y2='{sy - 12}' stroke='{OK}' stroke-width='2' marker-end='url(#bb1)'/>")
    p.append("<defs><marker id='bb1' markerWidth='8' markerHeight='8' refX='7' refY='4' orient='auto'>"
             f"<path d='M0,0 L8,4 L0,8 z' fill='{OK}'/></marker></defs>")
    p.append(_txt(sx + 12, sy - 30, "F = 900 N", 11, OK, "start", True))
    p.append(f"<rect x='40' y='300' width='680' height='68' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 323, "Le levier bascule autour de son axe : le vérin pousse à 40 mm, la pièce", 12, TRAIT, "start", True))
    p.append(_txt(56, 343, "est serrée à 65 mm. C'est ce rapport de bras qui gouverne toute la partie C", 12, FIN))
    p.append(_txt(56, 361, "de l'étude de cas — avant même de parler de résistance.", 12, FIN))
    return _svg("".join(p), 760, 387)


# ===========================================================================
# 84. SCHÉMA DU SYSTÈME — RÉDUCTEUR DE TAPIS (étude de cas 14.2)
# ===========================================================================

def schema_reducteur_etude_cas():
    p = [_txt(40, 24, "La chaîne de puissance de l'étude de cas, du moteur au tambour :",
              13, TRAIT, "start", True)]
    etapes = [
        (70, "MOTEUR", "4 kW", "1450 tr/min", FIN),
        (250, "PIGNON Z₁=20", "m = 1,5", "Ø30", ALESAGE),
        (430, "ROUE Z₂=100", "Ø150", "290 tr/min", ARBRE),
        (610, "TAMBOUR", "roulement", "charge 4200 N", OK),
    ]
    for x0, nom, l1, l2, couleur in etapes:
        p.append(f"<rect x='{x0}' y='90' width='100' height='70' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        p.append(_txt(x0 + 50, 114, nom, 11, couleur, "middle", True))
        p.append(_txt(x0 + 50, 132, l1, 10, FIN, "middle"))
        p.append(_txt(x0 + 50, 148, l2, 10, FIN, "middle"))
    # les flèches défilent : plus vite avant la réduction, plus lentement après —
    # on VOIT la vitesse chuter et, en contrepartie, le couple monter.
    for _i, x0 in enumerate((170, 350, 530)):
        vitesse = ".5s" if _i < 1 else ("1.6s" if _i == 1 else "2.4s")
        p.append(f"<line x1='{x0}' y1='125' x2='{x0 + 78}' y2='125' stroke='{FIN}' stroke-width='2.4' "
                 f"marker-end='url(#cc1)' stroke-dasharray='7 5'>"
                 f"<animate attributeName='stroke-dashoffset' values='0;-24' dur='{vitesse}' "
                 f"repeatCount='indefinite'/></line>")
    p.append("<defs><marker id='cc1' markerWidth='9' markerHeight='9' refX='8' refY='4.5' orient='auto'>"
             f"<path d='M0,0 L9,4.5 L0,9 z' fill='{FIN}'/></marker></defs>")
    p.append(_txt(210, 116, "Mt₁ = 26,3 N·m", 9, FIN, "middle"))
    p.append(_txt(390, 116, "r = 1/5", 9, FIN, "middle"))
    p.append(_txt(570, 116, "Mt₂ = 127,8 N·m", 9, FIN, "middle"))
    p.append(f"<rect x='40' y='185' width='680' height='90' fill='#fff7ed' stroke='{ARBRE}' rx='6'/>")
    p.append(_txt(56, 208, "La vitesse est divisée par 5 → le couple est MULTIPLIÉ par 5 (au rendement", 12, TRAIT, "start", True))
    p.append(_txt(56, 226, "près). C'est pourquoi l'arbre de sortie, qui reprend 127,8 N·m, doit être", 12, FIN))
    p.append(_txt(56, 244, "vérifié en flexion-torsion — c'est tout l'objet de la partie B du sujet —", 12, FIN))
    p.append(_txt(56, 262, "alors que l'arbre d'entrée, à 26,3 N·m seulement, ne pose aucun problème.", 12, FIN))
    return _svg("".join(p), 760, 285)


# ===========================================================================
# 85. LA MÉTHODE DE LA SYNTHÈSE DE DOCUMENTS
# ===========================================================================

def methode_synthese():
    p = [_txt(40, 24, "Quatre documents, une seule voix : la vôtre, qui les organise :",
              13, TRAIT, "start", True)]
    etapes = [
        ("1", "LIRE", "survol de chaque document : thème, thèse, type (article, graphique, image)", ALESAGE),
        ("2", "CONFRONTER", "quels documents se répondent, se complètent, se contredisent ?", ALESAGE),
        ("3", "PLANIFIER", "2 ou 3 axes, chacun nourri par PLUSIEURS documents", ARBRE),
        ("4", "RÉDIGER", "reformuler avec VOS mots, jamais recopier ni citer votre avis", OK),
    ]
    x = 60
    for _i, (num, titre, detail, couleur) in enumerate(etapes):
        # les 4 étapes s'éclairent dans l'ordre : LIRE, CONFRONTER, PLANIFIER, RÉDIGER.
        p.append(f"<rect x='{x}' y='55' width='150' height='150' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'>"
                 f"<animate attributeName='stroke-width' values='2;4;2;2' dur='4.8s' begin='{_i * 1.1}s' "
                 f"repeatCount='indefinite'/></rect>")
        p.append(f"<circle cx='{x + 75}' cy='85' r='16' fill='{couleur}'/>")
        p.append(_txt(x + 75, 91, num, 14, "#ffffff", "middle", True))
        p.append(_txt(x + 75, 118, titre, 12, couleur, "middle", True))
        mots = detail.split(" ")
        ligne = ""
        yy = 138
        for mo in mots:
            if len(ligne + mo) > 20:
                p.append(_txt(x + 75, yy, ligne.strip(), 9, FIN, "middle"))
                ligne = ""
                yy += 14
            ligne += mo + " "
        if ligne:
            p.append(_txt(x + 75, yy, ligne.strip(), 9, FIN, "middle"))
        x += 165
    p.append(f"<rect x='40' y='225' width='680' height='68' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 248, "L'erreur qui coûte le plus de points : résumer les documents L'UN APRÈS L'AUTRE.",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 268, "Une vraie synthèse croise les sources dans CHAQUE paragraphe — jamais un", 12, FIN))
    p.append(_txt(56, 286, "paragraphe = un document.", 12, FIN))
    return _svg("".join(p), 760, 310)


# ===========================================================================
# 86. LE PLAN D'UNE ARGUMENTATION
# ===========================================================================

def plan_argumentation():
    p = [_txt(40, 24, "Une thèse défendue ne suffit pas : il faut montrer que vous avez pesé le pour et le contre :",
              13, TRAIT, "start", True)]
    blocs_ = [
        (60, "INTRODUCTION", "reformuler le sujet, annoncer le plan", FIN),
        (60, "THÈSE 1", "des arguments EXPLIQUÉS, chacun avec un exemple précis", ALESAGE),
        (60, "THÈSE 2 (nuance)", "les limites de la thèse 1 : ce qu'elle n'explique pas", ARBRE),
        (60, "CONCLUSION", "une réponse personnelle, qui ne répète pas l'intro", OK),
    ]
    y = 55
    for _i, (x, titre, detail, couleur) in enumerate(blocs_):
        # les 4 blocs s'éclairent dans l'ordre : intro, thèse, nuance, conclusion.
        p.append(f"<rect x='{x}' y='{y}' width='660' height='46' rx='6' fill='#ffffff' stroke='{couleur}' stroke-width='1.8'/>")
        p.append(f"<rect x='{x}' y='{y}' width='10' height='46' fill='{couleur}'>"
                 f"<animate attributeName='width' values='10;18;10;10' dur='4.4s' begin='{_i * 1.1}s' "
                 f"repeatCount='indefinite'/></rect>")
        p.append(_txt(x + 26, y + 20, titre, 12, couleur, "start", True))
        p.append(_txt(x + 26, y + 37, detail, 10, FIN, "start"))
        y += 54
    p.append(f"<rect x='40' y='{y + 10}' width='680' height='66' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, y + 33, "Un argument sans exemple ne convainc personne : « c'est important » ne", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 53, "prouve rien. Un fait précis, une date, un chiffre, un auteur nommé le fait.", 12, FIN))
    return _svg("".join(p), 760, y + 90)


# ===========================================================================
# 87. LA RELECTURE EN TROIS PASSAGES
# ===========================================================================

def relecture_trois_passages():
    p = [_txt(40, 24, "Une relecture unique 'pour le sens' ne voit presque aucune faute d'accord :",
              13, TRAIT, "start", True)]
    passages = [
        (60, "1er PASSAGE", "LE SENS", "la copie répond-elle au sujet ? l'enchaînement est-il logique ?", ALESAGE),
        (60, "2e PASSAGE", "LES ACCORDS", "sujet-verbe, adjectifs, participes passés avec avoir", ARBRE),
        (60, "3e PASSAGE", "PONCTUATION", "a/à, on/ont, ce/se, ces/ses", OK),
    ]
    y = 55
    for _i, (x, num, titre, detail, couleur) in enumerate(passages):
        # les 3 passages s'éclairent dans l'ordre : sens, accords, ponctuation —
        # trois lectures différentes, jamais une seule.
        p.append(f"<rect x='{x}' y='{y}' width='660' height='56' rx='6' fill='#ffffff' stroke='{couleur}' stroke-width='1.8'>"
                 f"<animate attributeName='stroke-width' values='1.8;4;1.8;1.8' dur='4.2s' begin='{_i * 1.4}s' "
                 f"repeatCount='indefinite'/></rect>")
        p.append(f"<rect x='{x}' y='{y}' width='130' height='56' fill='{couleur}' opacity='0.12'/>")
        p.append(_txt(x + 65, y + 24, num, 11, couleur, "middle", True))
        p.append(_txt(x + 65, y + 42, titre, 11, couleur, "middle", True))
        p.append(_txt(x + 150, y + 33, detail, 11, TRAIT, "start"))
        y += 64
    p.append(f"<rect x='40' y='{y + 10}' width='680' height='66' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, y + 33, "L'œil corrige inconsciemment les fautes en lisant pour le sens : c'est pour cela", 12, TRAIT, "start", True))
    p.append(_txt(56, y + 53, "qu'un seul passage de relecture laisse passer la majorité des erreurs d'accord.", 12, FIN))
    return _svg("".join(p), 760, y + 90)


# ===========================================================================
# 88. DESSIN DE DÉFINITION À LIRE (atelier chapitre 1)
# ===========================================================================

def dessin_definition_atelier():
    p = []
    # --- cadre general ---
    p.append(f"<rect x='30' y='20' width='700' height='430' fill='none' stroke='{TRAIT}' stroke-width='2'/>")

    # --- VUE DE FACE : piece en L, en haut a gauche ---
    p.append(_txt(155, 46, "VUE DE FACE", 11, FIN, "middle", True))
    ox, oy = 80, 82
    p.append(f"<path d='M{ox},{oy} L{ox+150},{oy} L{ox+150},{oy+30} L{ox+40},{oy+30} "
             f"L{ox+40},{oy+120} L{ox},{oy+120} Z' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
    # trou dans la semelle verticale (vu de face = cercle)
    p.append(f"<circle cx='{ox+20}' cy='{oy+95}' r='11' fill='{FOND}' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(f"<line x1='{ox+20}' y1='{oy+78}' x2='{ox+20}' y2='{oy+112}' stroke='{AXE}' stroke-width='1' stroke-dasharray='6 3 2 3'/>")
    p.append(f"<line x1='{ox+3}' y1='{oy+95}' x2='{ox+37}' y2='{oy+95}' stroke='{AXE}' stroke-width='1' stroke-dasharray='6 3 2 3'/>")
    # cotes vue de face
    p.append(f"<line x1='{ox}' y1='{oy-12}' x2='{ox+150}' y2='{oy-12}' stroke='{FIN}' stroke-width='1'/>")
    p.append(_txt(ox+75, oy-16, "120", 11, TRAIT, "middle", True))
    p.append(f"<line x1='{ox-14}' y1='{oy}' x2='{ox-14}' y2='{oy+120}' stroke='{FIN}' stroke-width='1'/>")
    p.append(f"<text x='{ox-18}' y='{oy+60}' {_POLICE} font-size='11' fill='{TRAIT}' font-weight='700' text-anchor='middle' transform='rotate(-90 {ox-18},{oy+60})'>80</text>")
    p.append(_txt(ox+62, oy+95, "Ø14", 11, ALESAGE, "start", True))

    # --- VUE DE DESSUS : en dessous, alignee ---
    p.append(_txt(155, 232, "VUE DE DESSUS", 11, FIN, "middle", True))
    dx, dy = 80, 250
    p.append(f"<rect x='{dx}' y='{dy}' width='150' height='90' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
    # arete du dos vertical (vue de dessus)
    p.append(f"<line x1='{dx+40}' y1='{dy}' x2='{dx+40}' y2='{dy+90}' stroke='{TRAIT}' stroke-width='2'/>")
    # trou Ø14 vu de dessus = pointilles (il est perce horizontalement dans le dos)
    p.append(f"<line x1='{dx+8}' y1='{dy+30}' x2='{dx+8}' y2='{dy+60}' stroke='{TRAIT}' stroke-width='1.4' stroke-dasharray='5 3'/>")
    p.append(f"<line x1='{dx+32}' y1='{dy+30}' x2='{dx+32}' y2='{dy+60}' stroke='{TRAIT}' stroke-width='1.4' stroke-dasharray='5 3'/>")
    # cote largeur
    p.append(f"<line x1='{dx-14}' y1='{dy}' x2='{dx-14}' y2='{dy+90}' stroke='{FIN}' stroke-width='1'/>")
    p.append(f"<text x='{dx-18}' y='{dy+45}' {_POLICE} font-size='11' fill='{TRAIT}' font-weight='700' text-anchor='middle' transform='rotate(-90 {dx-18},{dy+45})'>60</text>")
    p.append(f"<line x1='{dx}' y1='{dy+104}' x2='{dx+40}' y2='{dy+104}' stroke='{FIN}' stroke-width='1'/>")
    p.append(_txt(dx+20, dy+118, "20", 11, TRAIT, "middle", True))

    # trait d'axe de correspondance entre les deux vues — le pointillé défile doucement :
    # on VOIT le lien entre la vue de face et la vue de dessus, sans gêner la lecture.
    p.append(f"<line x1='{ox+20}' y1='{oy+130}' x2='{ox+20}' y2='{dy-8}' stroke='{AXE}' stroke-width='0.8' "
             f"stroke-dasharray='4 4'><animate attributeName='stroke-dashoffset' values='0;-16' "
             f"dur='2.4s' repeatCount='indefinite'/></line>")

    # --- COUPE A-A a droite ---
    p.append(_txt(500, 46, "COUPE A-A", 11, FIN, "middle", True))
    cx, cy = 400, 70
    p.append(f"<path d='M{cx},{cy} L{cx+150},{cy} L{cx+150},{cy+30} L{cx+40},{cy+30} "
             f"L{cx+40},{cy+120} L{cx},{cy+120} Z' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    # hachures de la matiere coupee
    for i in range(14):
        x1 = cx + i*11
        if x1 > cx + 150:
            break
        p.append(f"<line x1='{x1}' y1='{cy}' x2='{min(x1+30, cx+150)}' y2='{cy+30}' stroke='{FIN}' stroke-width='0.8'/>")
    for i in range(9):
        y1 = cy + 30 + i*11
        p.append(f"<line x1='{cx}' y1='{y1}' x2='{cx+40}' y2='{min(y1+40, cy+120)}' stroke='{FIN}' stroke-width='0.8'/>")
    # le trou apparait en trait FORT dans la coupe
    p.append(f"<rect x='{cx+9}' y='{cy+84}' width='22' height='22' fill='{FOND}' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(_txt(cx+70, cy+98, "le trou devient", 10, OK, "start", True))
    p.append(_txt(cx+70, cy+112, "un trait FORT", 10, OK, "start", True))

    # --- CARTOUCHE en bas a droite ---
    bx, by = 400, 250
    p.append(f"<rect x='{bx}' y='{by}' width='300' height='150' fill='#ffffff' stroke='{TRAIT}' stroke-width='1.8'/>")
    lignes_c = [
        ("Titre", "ÉQUERRE SUPPORT"),
        ("Matière", "S235"),
        ("Échelle", "1:2"),
        ("Tol. générales", "ISO 2768-m"),
        ("Indice", "B"),
    ]
    yy = by + 26
    for lab, val in lignes_c:
        p.append(f"<line x1='{bx}' y1='{yy-18}' x2='{bx+300}' y2='{yy-18}' stroke='{FIN}' stroke-width='0.8'/>")
        p.append(_txt(bx+10, yy, lab, 10, FIN, "start"))
        p.append(_txt(bx+120, yy, val, 11, TRAIT, "start", True))
        yy += 26
    # symbole projection europeenne (cone tronque)
    p.append(f"<circle cx='{bx+250}' cy='{by+120}' r='13' fill='none' stroke='{TRAIT}' stroke-width='1.4'/>")
    p.append(f"<circle cx='{bx+250}' cy='{by+120}' r='7' fill='none' stroke='{TRAIT}' stroke-width='1.4'/>")
    p.append(f"<path d='M{bx+218},{by+110} L{bx+238},{by+120} L{bx+218},{by+130} Z' fill='none' stroke='{TRAIT}' stroke-width='1.4'/>")
    p.append(_txt(bx+150, by+124, "projection :", 10, FIN, "start"))

    return _svg("".join(p), 760, 470)


# ===========================================================================
# 89-90. SADT (actigramme) et grille AMDEC
# ===========================================================================

def sadt_actigramme():
    p = []
    p.append(_txt(340, 24, "L'actigramme A-0 : une boîte, quatre familles de flèches", 13, TRAIT, "middle", True))

    bx, by, bw, bh = 230, 120, 230, 130
    p.append(f"<rect x='{bx}' y='{by}' width='{bw}' height='{bh}' rx='6' fill='#dbeafe' stroke='{TRAIT}' stroke-width='2.4'/>")
    p.append(_txt(bx+bw/2, by+58, "VERBE À L'INFINITIF", 13, TRAIT, "middle", True))
    p.append(_txt(bx+bw/2, by+80, "(la fonction du système)", 10, FIN, "middle"))
    p.append(_txt(bx+bw-8, by+bh-8, "A-0", 10, FIN, "end", True))

    # ENTREE (gauche) — le flux défile vers la boîte : on VOIT la matière/énergie entrer.
    p.append(f"<line x1='60' y1='{by+65}' x2='{bx-4}' y2='{by+65}' stroke='{OK}' stroke-width='2.4' "
             f"marker-end='url(#fl)' stroke-dasharray='7 5'>"
             f"<animate attributeName='stroke-dashoffset' values='0;-24' dur='1.2s' repeatCount='indefinite'/></line>")
    p.append(_txt(60, by+52, "ENTRÉE", 11, OK, "start", True))
    p.append(_txt(60, by+90, "matière, énergie", 10, FIN, "start"))
    p.append(_txt(60, by+104, "ou information", 10, FIN, "start"))
    p.append(_txt(60, by+118, "AVANT transformation", 10, FIN, "start"))

    # SORTIE (droite) — même flux qui continue de défiler, après transformation.
    p.append(f"<line x1='{bx+bw+4}' y1='{by+65}' x2='{bx+bw+180}' y2='{by+65}' stroke='{ALESAGE}' "
             f"stroke-width='2.4' marker-end='url(#fl)' stroke-dasharray='7 5'>"
             f"<animate attributeName='stroke-dashoffset' values='0;-24' dur='1.2s' repeatCount='indefinite'/></line>")
    p.append(_txt(bx+bw+10, by+52, "SORTIE", 11, ALESAGE, "start", True))
    p.append(_txt(bx+bw+10, by+90, "le MÊME flux,", 10, FIN, "start"))
    p.append(_txt(bx+bw+10, by+104, "après transformation", 10, FIN, "start"))

    # CONTROLES (haut) — les 4 pilotes s'éclairent l'un après l'autre, jamais ensemble.
    for i, lab in enumerate(["W", "C", "R", "E"]):
        x = bx + 30 + i*55
        p.append(f"<line x1='{x}' y1='{by-58}' x2='{x}' y2='{by-4}' stroke='{ARBRE}' stroke-width='2' marker-end='url(#fl)'>"
                 f"<animate attributeName='stroke-width' values='2;3.6;2;2;2;2;2;2' dur='4.8s' "
                 f"begin='{i * 0.6}s' repeatCount='indefinite'/></line>")
        p.append(_txt(x, by-64, lab, 11, ARBRE, "middle", True))
    p.append(_txt(bx+bw/2, by-80, "CONTRÔLES (ce qui pilote, ne se transforme pas)", 10, ARBRE, "middle", True))

    # MECANISME (bas) — le flux monte vers la boîte : ce qui réalise l'action.
    p.append(f"<line x1='{bx+bw/2}' y1='{by+bh+58}' x2='{bx+bw/2}' y2='{by+bh+4}' stroke='{FIN}' "
             f"stroke-width='2' marker-end='url(#fl)' stroke-dasharray='6 4'>"
             f"<animate attributeName='stroke-dashoffset' values='0;-20' dur='1.4s' repeatCount='indefinite'/></line>")
    p.append(_txt(bx+bw/2, by+bh+76, "MÉCANISME — ce qui réalise (la matière d'œuvre du support)", 10, FIN, "middle", True))

    # legende WCRE
    yl = 340
    p.append(f"<rect x='60' y='{yl}' width='620' height='72' rx='6' fill='{FOND}' stroke='{FIN}' stroke-width='1'/>")
    for i,(l,t) in enumerate([("W","énergie (Watt)"),("C","configuration / réglage"),
                               ("R","réglage / consigne"),("E","exploitation / marche-arrêt")]):
        p.append(_txt(76 + (i%2)*310, yl+26+(i//2)*26, f"{l} —", 11, ARBRE, "start", True))
        p.append(_txt(108 + (i%2)*310, yl+26+(i//2)*26, t, 11, TRAIT, "start"))

    defs = ("<defs><marker id='fl' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' "
            f"markerHeight='6' orient='auto'><path d='M0,0 L10,5 L0,10 z' fill='{TRAIT}'/></marker></defs>")
    return _svg(defs + "".join(p), 720, 430)


def grille_amdec():
    p = []
    p.append(_txt(360, 24, "La grille AMDEC : de la défaillance à l'action", 13, TRAIT, "middle", True))

    cols = [("Fonction", 60), ("Mode de\ndéfaillance", 150), ("Cause", 250),
            ("Effet", 340), ("G", 430), ("O", 470), ("D", 510), ("C = G×O×D", 550), ("Action", 640)]
    y0 = 52
    p.append(f"<rect x='50' y='{y0}' width='620' height='36' fill='#dbeafe' stroke='{TRAIT}' stroke-width='1.4'/>")
    for lab, x in cols:
        for k, part in enumerate(lab.split("\n")):
            p.append(_txt(x, y0+22+k*12-(6 if "\n" in lab else 0), part, 10, TRAIT, "start", True))

    lignes = [("Guider en", "Grippage", "Défaut de", "Arrêt", "4", "2", "3", "24", "Contrôle jeu"),
              ("rotation", "du palier", "lubrification", "machine", "", "", "", "", "au montage"),
              ("Transmettre", "Rupture", "Sous-", "Perte", "5", "3", "4", "60", "Recalculer,"),
              ("le couple", "clavette", "dimensionnt", "fonction", "", "", "", "", "cannelures")]
    for i, ligne in enumerate(lignes):
        y = y0 + 44 + i*24
        if i % 2 == 0:
            p.append(f"<rect x='50' y='{y-16}' width='620' height='48' fill='{'#f8fafc' if i==0 else '#fef2f2'}' stroke='{FIN}' stroke-width='0.8'/>")
        for (lab, x), val in zip(cols, ligne):
            coul = ALERTE if (i >= 2 and lab in ("G","O","D","C = G×O×D")) else TRAIT
            gras = lab in ("G","O","D","C = G×O×D")
            if val == "60":
                # la criticité qui dépasse le seuil clignote : on VOIT pourquoi l'action
                # est obligatoire sur cette ligne précisément.
                p.append(f"<rect x='{x - 4}' y='{y - 12}' width='26' height='16' fill='{ALERTE}' opacity='0'>"
                         f"<animate attributeName='opacity' values='0;0.25;0' dur='1.2s' "
                         f"repeatCount='indefinite'/></rect>")
            p.append(_txt(x, y, val, 10, coul, "start", gras))

    yb = 196
    p.append(f"<rect x='50' y='{yb}' width='620' height='96' rx='6' fill='{FOND}' stroke='{FIN}' stroke-width='1'/>")
    p.append(_txt(64, yb+24, "G — Gravité de l'effet pour l'utilisateur", 11, TRAIT, "start", True))
    p.append(_txt(64, yb+46, "O — Occurrence : la fréquence d'apparition", 11, TRAIT, "start", True))
    p.append(_txt(64, yb+68, "D — Détection : 1 = on le voit tout de suite · 10 = invisible avant la panne", 11, TRAIT, "start", True))
    p.append(_txt(64, yb+88, "C = G × O × D : au-delà du seuil fixé (souvent 40 à 100), une action est OBLIGATOIRE",
                  11, ALERTE, "start", True))
    return _svg("".join(p), 720, 320)


