# ATELIERS — moteur en six temps nommés, avec diagnostic par erreur prévisible
# ===========================================================================

_SIX_TEMPS = [
    ("enonce", "1. Ce que dit l'énoncé"),
    ("regle", "2. Quelle règle, et pourquoi"),
    ("conversions", "3. Les conversions"),
    ("remplacement", "4. Le remplacement"),
    ("calcul", "5. Le calcul"),
    ("verification", "6. La vérification"),
]



# ===========================================================================
# VIDÉOS — recherches YouTube ciblées par fiche
# ===========================================================================

_MOTS_VIDEO = {
    "1": "analyse fonctionnelle", "2": "tolérancement ISO", "3": "matériaux mécanique",
    "4": "résistance des matériaux", "5": "lecture de plan CAO", "6": "liaisons mécaniques",
    "7": "mathématiques BTS", "8": "physique appliquée", "9": "SolidWorks",
    "10": "anglais technique mécanique", "11": "BTS CPI", "12": "statique mécanique",
    "13": "plasturgie soudage", "14": "étude de cas mécanique", "15": "méthode BTS",
    "16": "culture générale BTS",
}


def _requetes_video(fiche, bloc_id):
    """Construit 3 recherches YouTube : la fiche, sa notion clé, et une version débutant."""
    titre = re.sub(r"[^\w\s'àâäéèêëîïôöùûüç-]", " ", fiche.get("titre", ""))
    titre = re.sub(r"\s+", " ", titre).strip()
    domaine = _MOTS_VIDEO.get(str(bloc_id).replace("bloc", ""), "mécanique")
    return [
        (f"{titre} — cours", f"{titre} {domaine} cours"),
        (f"{titre} — expliqué simplement", f"{titre} expliqué simplement"),
        (f"{domaine} — BTS CPI", f"{domaine} BTS CPI cours"),
    ]


def _lien_youtube(requete):
    from urllib.parse import quote_plus
    return "https://www.youtube.com/results?search_query=" + quote_plus(requete)


def _rendre_atelier(_at, _prefixe):
    """Atelier pas à pas : l'élève entre CHAQUE valeur intermédiaire et
    n'accède à l'étape suivante qu'après l'avoir trouvée. Chaque mauvaise
    réponse prévisible reçoit son propre diagnostic. Le corrigé complet se
    dévoile ensuite en six temps nommés, un par un."""

    _cle_etape = f"{_prefixe}_at_etape"
    _cle_hist = f"{_prefixe}_at_hist"
    _cle_temps = f"{_prefixe}_at_temps"
    if _cle_etape not in st.session_state:
        st.session_state[_cle_etape] = 0
        st.session_state[_cle_hist] = []
        st.session_state[_cle_temps] = 0

    _cnav1, _cnav2 = st.columns(2)
    with _cnav1:
        if st.button("← Étape précédente", key=f"{_prefixe}_at_prev",
                     disabled=st.session_state[_cle_etape] == 0):
            st.session_state[_cle_etape] = max(0, st.session_state[_cle_etape] - 1)
            if st.session_state[_cle_hist]:
                st.session_state[_cle_hist].pop()
            st.session_state[_cle_temps] = 0
            st.rerun()
    with _cnav2:
        if st.button("↺ Recommencer cet atelier", key=f"{_prefixe}_at_reset"):
            st.session_state[_cle_etape] = 0
            st.session_state[_cle_hist] = []
            st.session_state[_cle_temps] = 0
            st.rerun()

    # --- Vocabulaire traduit, avant toute chose ---
    if _at.get("vocabulaire"):
        with st.expander("📖 Glossaire — les mots de cet atelier (à lire, rien à cliquer)",
                         expanded=False):
            st.caption("Ce n'est pas un menu : c'est la liste des termes techniques employés "
                       "dans l'atelier, traduits en français courant.")
            _tab = "| Terme | Ce que ça veut dire |\n|---|---|\n"
            for _mot, _sens in _at["vocabulaire"]:
                _tab += f"| **{_mot}** | {_sens} |\n"
            st.markdown(_tab)

    # --- Le document à exploiter ---
    st.write("")
    st.markdown("#### Le document")
    if _at.get("figure"):
        afficher_contenu(f"[[FIG:{_at['figure']}]]")
    if _at.get("document"):
        st.markdown(_at["document"])

    st.write("")
    with st.container(border=True):
        st.markdown(f"**{_at['titre']}**")
        st.markdown(_at["enonce"])

    _idx = st.session_state[_cle_etape]
    _n = len(_at["etapes"])

    st.write("")
    st.progress(min(_idx / _n, 1.0))

    # --- Historique des valeurs déjà trouvées ---
    for _h in st.session_state[_cle_hist]:
        st.markdown(
            f'<div class="ok-box" style="margin-bottom:8px">✅ <b>{_h["label"]}</b> = '
            f'{_h["valeur"]}</div>', unsafe_allow_html=True)

    # --- L'étape en cours : l'élève doit trouver la valeur ---
    if _idx < _n:
        _et = _at["etapes"][_idx]
        st.markdown(f"#### Étape {_idx + 1}/{_n} — {_et['label']}")
        if _et.get("consigne"):
            st.markdown(_et["consigne"])

        _type = _et.get("type", "numerique")
        _cle_in = f"{_prefixe}_at_in_{_idx}"

        if _type == "qcm":
            _rep = st.radio(_et.get("question", "Votre réponse"), _et["options"],
                            key=_cle_in, index=None)
            _go = st.button("Valider", type="primary", key=f"{_prefixe}_at_go_{_idx}")
            if _go and _rep is None:
                st.warning("Choisissez d'abord une réponse ci-dessus.")
                _go = False
            if _et.get("indice"):
                with st.popover("💡 Indice"):
                    st.write(_et["indice"])
            if _go and _rep is not None:
                _i = _et["options"].index(_rep)
                if _i == _et["bonne"]:
                    st.session_state[_cle_hist].append(
                        {"label": _et["label"], "valeur": _rep})
                    st.session_state[_cle_etape] += 1
                    st.rerun()
                else:
                    # diagnostic PROPRE A CETTE mauvaise reponse
                    _diag = _et.get("diagnostics", {}).get(_i)
                    st.markdown(
                        f'<div class="ko-box"><b>Pas encore.</b> Vous avez choisi '
                        f'« {_rep} ».</div>', unsafe_allow_html=True)
                    if _diag:
                        st.markdown(f'<div class="warn-box">🔍 <b>Ce qui a dû se passer —</b> '
                                    f'{_diag}</div>', unsafe_allow_html=True)
                    if st.button("Voir la réponse et continuer",
                                 key=f"{_prefixe}_at_skip_{_idx}"):
                        st.session_state[_cle_hist].append(
                            {"label": _et["label"] + " (donnée)",
                             "valeur": _et["options"][_et["bonne"]]})
                        st.session_state[_cle_etape] += 1
                        st.rerun()
        else:
            _val = st.number_input(
                f"Votre valeur ({_et['unite']})" if _et.get("unite") else "Votre valeur",
                value=None, format="%.4f", step=0.001, key=_cle_in)
            _go = st.button("Valider", type="primary", key=f"{_prefixe}_at_go_{_idx}")
            if _go and _val is None:
                st.warning("Entrez d'abord une valeur dans le champ ci-dessus, "
                           "puis appuyez sur Valider.")
                _go = False
            if _et.get("indice"):
                with st.popover("💡 Indice"):
                    st.write(_et["indice"])
            if _go and _val is not None:
                _att = _et["attendu"]
                _tol = _et.get("tol", 0.02)
                if abs(_val - _att) <= max(abs(_att) * _tol, 1e-9):
                    st.session_state[_cle_hist].append(
                        {"label": _et["label"],
                         "valeur": f"{_val:g} {_et.get('unite','')}".strip()})
                    st.session_state[_cle_etape] += 1
                    st.rerun()
                else:
                    st.markdown(
                        f'<div class="ko-box"><b>Pas encore.</b> Vous avez entré '
                        f'<b>{_val:g}</b>, la valeur attendue est <b>{_att:g} '
                        f'{_et.get("unite","")}</b>.</div>', unsafe_allow_html=True)
                    # diagnostic sur valeur fausse PREVISIBLE, sinon heuristique
                    # générique (facteur 2, conversion d'unité, signe...), sinon l'aide
                    # de l'étape : jamais de "faux" sans explication.
                    _trouve = None
                    for _piege, _msg in _et.get("pieges", []):
                        if abs(_val - _piege) <= max(abs(_piege) * 0.02, 1e-9):
                            _trouve = _msg
                            break
                    if not _trouve:
                        _trouve = _diagnostic_erreur(_val, _att)
                    if _trouve:
                        st.markdown(f'<div class="warn-box">🔍 <b>Ce qui a dû se passer —</b> '
                                    f'{_trouve}</div>', unsafe_allow_html=True)
                    if _et.get("aide"):
                        st.info(_et["aide"])
                    if st.button("Voir la valeur et continuer",
                                 key=f"{_prefixe}_at_skip_{_idx}"):
                        st.session_state[_cle_hist].append(
                            {"label": _et["label"] + " (donnée)",
                             "valeur": f"{_att:g} {_et.get('unite','')}".strip()})
                        st.session_state[_cle_etape] += 1
                        st.rerun()

    # --- Toutes les valeurs trouvées : le corrigé en six temps, un par un ---
    else:
        st.success("Toutes les valeurs sont trouvées. Voici le corrigé, temps par temps.")
        st.write("")
        _t = st.session_state[_cle_temps]
        _corr = _at["corrige"]
        for _k in range(min(_t + 1, len(_SIX_TEMPS))):
            _cle_t, _titre_t = _SIX_TEMPS[_k]
            st.markdown(f"##### {_titre_t}")
            st.markdown(_corr.get(_cle_t, "_(non renseigné)_"))
            st.markdown("<hr style='margin:8px 0 14px 0;border-color:#e5e7eb'>",
                        unsafe_allow_html=True)
        if _t + 1 < len(_SIX_TEMPS):
            _suivant = _SIX_TEMPS[_t + 1][1]
            if st.button(f"Dévoiler « {_suivant} »", type="primary",
                         key=f"{_prefixe}_at_next_temps"):
                st.session_state[_cle_temps] += 1
                st.rerun()
        else:
            st.info(_at.get("a_retenir", ""))
            return True
    return False


def _rendre_exercice_interactif(_ex, _prefixe):
    """Moteur pas à pas réutilisable : étapes numériques ou QCM, historique,
    diagnostic d'erreur, conclusion. Utilisé par la page Exercices guidés ET
    par les exercices générés depuis un document importé."""
    _cle_etat = f"{_prefixe}_etape"
    _cle_hist = f"{_prefixe}_historique"
    if _cle_etat not in st.session_state:
        st.session_state[_cle_etat] = 0
        st.session_state[_cle_hist] = []

    _c1, _c2 = st.columns(2)
    with _c1:
        if st.button("← Étape précédente", key=f"prev_{_prefixe}",
                     disabled=st.session_state[_cle_etat] == 0):
            st.session_state[_cle_etat] = max(0, st.session_state[_cle_etat] - 1)
            if st.session_state[_cle_hist]:
                st.session_state[_cle_hist].pop()
            st.rerun()
    with _c2:
        if st.button("↺ Recommencer cet exercice", key=f"reset_{_prefixe}"):
            st.session_state[_cle_etat] = 0
            st.session_state[_cle_hist] = []
            st.rerun()

    st.write("")
    with st.container(border=True):
        st.markdown(f"**{_ex['titre']}**")
        st.markdown(_ex["enonce"])

    _etape_idx = st.session_state[_cle_etat]
    _total_etapes = len(_ex["etapes"]) + 1  # +1 pour la conclusion

    st.write("")
    st.progress(_etape_idx / _total_etapes)

    # --- Historique des étapes déjà validées ---
    for _h in st.session_state[_cle_hist]:
        if str(_h.get("unite", "")).startswith("✓"):
            _ligne_h = f'{_h["unite"]}'
        else:
            _ligne_h = f'{_h["valeur"]:g} {_h["unite"]}'
        st.markdown(
            f'<div class="ok-box" style="margin-bottom:8px">✅ <b>{_h["label"]}</b> = '
            f'{_ligne_h}</div>', unsafe_allow_html=True)

    # --- Étape en cours (numérique ou QCM) ---
    if _etape_idx < len(_ex["etapes"]):
        _et = _ex["etapes"][_etape_idx]
        _type_etape = _et.get("type", "numerique")
        st.markdown(f"#### Étape {_etape_idx + 1}/{len(_ex['etapes'])} — {_et['label']}")

        if _et.get("texte"):
            st.markdown(
                f'<div class="warn-box" style="font-style:italic">« {_et["texte"]} »</div>',
                unsafe_allow_html=True)

        if _type_etape == "qcm":
            _cle_rep = f"{_prefixe}_qcm_{_etape_idx}"
            _rep = st.radio(_et.get("question", "Votre réponse"), _et["options"],
                            key=_cle_rep, index=None)
            _valider = st.button("Valider cette étape", type="primary",
                                 key=f"{_prefixe}_valider_{_etape_idx}")
            if _valider and _rep is None:
                st.warning("Choisissez d'abord une réponse ci-dessus.")
                _valider = False
            if _et.get("indice"):
                with st.popover("💡 Indice"):
                    st.write(_et["indice"])

            if _valider and _rep is not None:
                _idx_rep = _et["options"].index(_rep)
                if _idx_rep == _et["bonne"]:
                    st.session_state[_cle_hist].append(
                        {"label": _et["label"], "valeur": 0, "unite": "✓ " + _rep})
                    st.session_state[_cle_etat] += 1
                    st.rerun()
                else:
                    st.markdown(
                        f'<div class="ko-box"><b>❌ Pas encore</b><br>'
                        f'Vous avez choisi « {_rep} ».</div>', unsafe_allow_html=True)
                    st.markdown(
                        f'<div class="warn-box">🔍 <b>Explication —</b> '
                        f'{_et["explication"]}</div>', unsafe_allow_html=True)
                    st.write("")
                    if st.button("Voir la bonne réponse et continuer",
                                 key=f"{_prefixe}_passer_{_etape_idx}"):
                        st.session_state[_cle_hist].append(
                            {"label": _et["label"] + " (donnée)", "valeur": 0,
                             "unite": "✓ " + _et["options"][_et["bonne"]]})
                        st.session_state[_cle_etat] += 1
                        st.rerun()

        else:
            _cle_input = f"{_prefixe}_input_{_etape_idx}"
            _val = st.number_input(
                f"Votre valeur ({_et['unite']})" if _et['unite'] else "Votre valeur",
                value=None, format="%.4f", key=_cle_input, step=0.01)

            c_valider, c_indice = st.columns([1, 1])
            with c_valider:
                _valider = st.button("Valider cette étape", type="primary",
                                     key=f"{_prefixe}_valider_{_etape_idx}")
            with c_indice:
                with st.popover("💡 Indice"):
                    st.write(f"Formule à utiliser : **{_et['formule']}**")

            if _valider and _val is None:
                st.warning("Entrez d'abord une valeur dans le champ ci-dessus, "
                           "puis appuyez sur Valider.")
            if _valider and _val is not None:
                _attendu = _et["attendu"]
                _tol = _et["tol"]
                _ok = abs(_val - _attendu) <= max(abs(_attendu) * _tol, 1e-9)
                if _ok:
                    st.session_state[_cle_hist].append(
                        {"label": _et["label"], "valeur": _val, "unite": _et["unite"]})
                    st.session_state[_cle_etat] += 1
                    st.rerun()
                else:
                    _diag = _diagnostic_erreur(_val, _attendu)
                    st.markdown(
                        f'<div class="ko-box"><b>❌ Pas encore</b><br>'
                        f'Vous avez entré <b>{_val:g}</b>, la valeur attendue est '
                        f'<b>{_attendu:g} {_et["unite"]}</b>.</div>', unsafe_allow_html=True)
                    if _diag:
                        st.markdown(f'<div class="warn-box">🔍 <b>Diagnostic —</b> {_diag}</div>',
                                  unsafe_allow_html=True)
                    st.info(f"**Formule à appliquer :** {_et['formule']}")
                    st.write("")
                    c_retry, c_pass = st.columns(2)
                    with c_retry:
                        st.caption("Corrigez votre valeur ci-dessus puis validez à nouveau.")
                    with c_pass:
                        if st.button("Voir la valeur correcte et continuer",
                                     key=f"{_prefixe}_passer_{_etape_idx}"):
                            st.session_state[_cle_hist].append(
                                {"label": _et["label"] + " (donnée)", "valeur": _attendu,
                                 "unite": _et["unite"]})
                            st.session_state[_cle_etat] += 1
                            st.rerun()

    # --- Conclusion (QCM) ---
    elif _etape_idx == len(_ex["etapes"]):
        _cc = _ex["conclusion"]
        st.markdown(f"#### Conclusion — {_cc['question']}")
        _rep = st.radio("Votre réponse", _cc["options"], key=f"{_prefixe}_concl", index=None)
        _vc = st.button("Valider la conclusion", type="primary",
                        key=f"{_prefixe}_valider_concl")
        if _vc and _rep is None:
            st.warning("Choisissez d'abord une réponse ci-dessus.")
            _vc = False
        if _vc:
            _idx_rep = _cc["options"].index(_rep)
            if _idx_rep == _cc["bonne"]:
                st.session_state[_cle_hist].append(
                    {"label": "Conclusion", "valeur": 0, "unite": "✓ correcte"})
                st.session_state[_cle_etat] += 1
                st.rerun()
            else:
                st.markdown('<div class="ko-box"><b>❌ Ce n\'est pas la bonne conclusion.</b>'
                           '</div>', unsafe_allow_html=True)
                st.info(_cc["explication"])

    # --- Exercice terminé ---
    else:
        st.balloons()
        st.success(f"🎉 Exercice terminé — **{_ex['titre']}**")
        st.markdown(f"**Ce qu'il fallait retenir :** {_ex['conclusion']['explication']}")
        return True
    return False


